add(251, [
'''יו מסקלה, חצוצרן מדרום אפריקה, עזב את ארצו בתחילת שנות השישים, כשמשטר האפרטהייד הקשה על מוזיקאים שחורים לחיות וליצור. הוא למד בלונדון ובניו יורק, התחתן עם מרים מקבה (אלבום 26), ובסוף שנות השישים כבר הגיע לראש המצעדים באמריקה עם להיט פופ אינסטרומנטלי. אבל בתחילת 1972 הוא נכנס לאולפן בלונדון עם חברים ותיקים מהגלות, בהם הסקסופוניסט דודו פוקוואנה והמתופף מקאיה נטשוקו, והקליט ביום אחד אלבום כפול, שחוזר לשורשים.''',
'''זה ג׳אז חם וחופשי, שנשען על מקצבים ועל מלודיות של דרום אפריקה. הפלוגלהורן של מסקלה, רך ועגול יותר מחצוצרה, והסקסופון הצורב של פוקוואנה מנהלים שיחה ארוכה מעל פסנתר, בס ותופים שלא מפסיקים לנוע. יש כאן קטעים שמחים ורוקדים, שנשמעים כמו מסיבה בשכונה של יוהנסבורג, ויש קטעים איטיים ועצובים, מלאי געגוע לבית שאי אפשר לחזור אליו. לפעמים מסקלה גם שר ומזמר בשפות של ארצו.''',
'''שם האלבום, "הבית הוא איפה שהמוזיקה", אומר הכול: לגולים, המוזיקה הייתה הדרך לשמור על הבית בתוך הלב. האלבום נחשב לאחד הטובים של מסקלה ולאחד החיבורים היפים בין ג׳אז אמריקאי למוזיקה אפריקאית. מסקלה חזר לדרום אפריקה רק אחרי שחרורו של נלסון מנדלה, ונשאר עד מותו ב־2018 אחד הקולות החשובים של המאבק באפרטהייד.''',
'''שמעו את האלבום כמו ששומעים הופעה במועדון קטן: לא שיר אחד, אלא רצף. אם אהבתם את הג׳אז האפריקאי של פלה קוטי (אלבום 232), כאן תשמעו צד אחר, שקט ונוגה יותר, של אותה יבשת.''',
], [
('The Big Apple', 'ג׳אז אנרגטי ושמח, עם פלוגלהורן וסקסופון שרודפים זה אחרי זה.'),
('Part of a Whole', 'קטע רגוע ונוגה, מלא געגוע לבית רחוק.'),
('Nomvula', 'מלודיה דרום אפריקאית יפה, עם קצב שמתגלגל בלי הפסקה.'),
])

add(252, [
'''בסוף שנות השישים, בעיר בלו הוריזונטה שבמדינת מינאס ז׳ראיס בברזיל, התאספה חבורה של מוזיקאים צעירים בפינת רחוב אחת, ומשם השם: "מועדון הפינה". בראשם עמדו מילטון נאסימנטו, זמר בעל קול יוצא דופן שכבר היה כוכב בברזיל, ולו בורז׳ס, נער בן עשרים שכתב שירים מלאי השראה מהביטלס. ב־1972, בזמן שלטון הגנרלים, הם הקליטו יחד אלבום כפול, עם חברים רבים מהחבורה.''',
'''קשה להגדיר את המוזיקה: יש בה סמבה ובוסה נובה, רוק פסיכדלי, פולק, מוזיקה של כנסיות ושירי עם מהכפרים של מינאס. הקול של נאסימנטו עולה לגבהים ויורד לעומקים, לפעמים בלי מילים בכלל, והשירים של בורז׳ס קלילים ומלודיים. Tudo Que Você Podia Ser פותח בגיטרה אקוסטית ובשירה נוגה, Cais הוא שיר שקט ורחב על יציאה לים, ו־O Trem Azul של לו בורז׳ס הוא אחד השירים האהובים בברזיל עד היום. יש כאן תזמורות, גיטרות חשמליות, חלילים וקולות רבים, והכול נשמע טבעי, כמו ערב בין חברים.''',
'''האלבום לא הצליח מיד, אבל עם השנים הוא הפך לאחד האלבומים הנערצים במוזיקה הברזילאית, ורבים בוחרים בו כטוב ביותר שנעשה שם אי פעם. מוזיקאי ג׳אז ופופ מכל העולם הושפעו ממנו, וכמה מחברי "מועדון הפינה" עשו אחר כך קריירות גדולות משלהם. העטיפה, צילום של שני ילדים יושבים בצד דרך עפר, הפכה לאחת התמונות המוכרות בברזיל.''',
'''זה אלבום ארוך, אז כדאי לחלק אותו לשניים. התחילו ב־Cais וב־O Trem Azul, ואז שמעו את כל השאר ברצף. אם אהבתם את השילוב של ברזיל ופסיכדליה אצל או מוטנטס (אלבום 112) ואצל קאטאנו ולוזו (אלבום 129), זה ההמשך הטבעי.''',
], [
('Cais', 'שיר שקט ורחב, שבו הקול של נאסימנטו עולה כמו גל.'),
('O Trem Azul', 'שיר מלודי ורך של לו בורז׳ס, מהאהובים בברזיל.'),
('Tudo Que Você Podia Ser', 'הפותח: גיטרה אקוסטית, קצב מתגלגל ושירה נוגה.'),
])

add(253, [
'''טוד רנדגרן היה ילד פלא של אולפני ההקלטה: בגיל עשרים ושתיים הוא כבר הפיק אלבומים של אחרים, ניגן כמעט על כל כלי, ולימד את עצמו להפעיל את מכשירי האולפן. ב־1972 הוא הוציא אלבום כפול, שבשלושה מתוך ארבעת הצדדים שלו הוא עשה הכול לבד: כתב, שר, ניגן והפיק. בצד הרביעי הצטרפו אליו נגנים, וחלק מהשירים הוקלטו כמעט בשידור חי באולפן.''',
'''התוצאה היא חגיגה של פופ: שירי אהבה מלודיים עם פסנתר והרמוניות, רוק עליז, קטעים משעשעים, ואפילו רגע שבו רנדגרן מסביר לשומעים איך נשמעת "רעשי הקלטה" באולפן. I Saw the Light, שפותח את האלבום, הוא שיר פופ מושלם ורך, ו־Hello It's Me, גרסה חדשה לשיר שכתב כנער, הפך ללהיט הגדול שלו. Couldn't I Just Tell You הוא רוק פופ מהיר עם גיטרות מצלצלות, ויש גם שירי נשמה בהשראת הסול של פילדלפיה.''',
'''Something/Anything? הראה שאמן אחד יכול להיות להקה שלמה, וזה השפיע על מוזיקאים רבים שהקליטו לבד בבית, מפרינס ועד אמני אינדי. רנדגרן עצמו לא נשאר במקום אחד: כבר באלבום הבא הוא פנה לכיוונים ניסיוניים ומוזרים הרבה יותר (אלבום 287), והמשיך לעבוד כמפיק מבוקש. אבל כאן, יותר מבכל מקום אחר, נשמע כשרון הפופ הטבעי שלו.''',
'''שמעו את I Saw the Light ואחריו את Hello It's Me, ותקשיבו איך כל כלי וכל קול באים מאותו אדם. אם אהבתם את ביג סטאר (אלבום 242), תמצאו כאן אותו חיבור לביטלס ולפופ מלודי.''',
], [
('I Saw the Light', 'הפותח: שיר פופ מושלם, רך ומלודי, עם פסנתר והרמוניות.'),
('Hello It\'s Me', 'הלהיט הגדול: בלדה חמה עם קולות ליווי וקצב רגוע.'),
('Couldn\'t I Just Tell You', 'רוק פופ מהיר עם גיטרות מצלצלות ואנרגיה של ביטלס.'),
])

add(254, [
'''חברי הניטי גריטי דירט בנד היו להקת קאנטרי־רוק צעירה מקליפורניה, עם שיער ארוך, כשהחליטו לעשות משהו שנראה אז כמעט בלתי אפשרי: לנסוע לנאשוויל ולהקליט עם הוותיקים הגדולים של הקאנטרי והבלוגראס, שחלקם חשדו מאוד בהיפים. באוגוסט 1971 הגיעו לאולפן אמא מייבל קרטר מ"משפחת קרטר", רוי אקאף, "מלך הקאנטרי", הגיטריסט העיוור דוק ווטסון, נגן הבנג׳ו ארל סקראגס ועוד. התוצאה יצאה כאלבום משולש.''',
'''הקלטות פשוטות וחיות, כמעט בלי תיקונים: גיטרות אקוסטיות, בנג׳ו, כינור, מנדולינה וקולות. שומעים גם את השיחות בין השירים, הצחוקים וההתלבטויות, כאילו אתם יושבים באולפן. דוק ווטסון מנגן ושר את Tennessee Stud בגיטרה מהירה ומדויקת, רוי אקאף שר את Wabash Cannonball על רכבת מפורסמת, ואמא מייבל קרטר מובילה את Keep on the Sunny Side ואת שיר הנושא, שיר גוספל ישן על משפחה שנפרדת ושואלת אם תתאחד בשמיים.''',
'''האלבום נמכר הרבה מעבר לציפיות, והפך לגשר בין שני דורות ושני עולמות, בזמן שאמריקה הייתה מפולגת בגלל מלחמת וייטנאם. הוא הכיר לצעירים את שורשי הקאנטרי והבלוגראס, והחזיר את הוותיקים לבמה. ה"מעגל" שבשם השיר הפך לסמל: המוזיקה עוברת מדור לדור ולא נקטעת.''',
'''זה אלבום ארוך מאוד, אז אל תנסו לשמוע אותו בבת אחת. בחרו כמה שירים של כל אחד מהוותיקים, והשאירו את שיר הנושא לסוף. אם אהבתם את הלובין ברדרס (אלבום 3), כאן תשמעו את אותה מסורת, בקולות של מי שבנו אותה.''',
], [
('Will the Circle Be Unbroken', 'שיר הגוספל הישן, בהובלת אמא מייבל קרטר ובשירה של כולם.'),
('Tennessee Stud', 'דוק ווטסון בגיטרה מהירה ובסיפור מערבון על סוס ועל אהבה.'),
('Keep on the Sunny Side', 'שיר ישן ואופטימי של משפחת קרטר, בקולה של אמא מייבל.'),
])

add(255, [
'''סטיבי וונדר התחיל להקליט במוטאון בגיל אחת־עשרה, והיה במשך שנים "ילד הפלא" של החברה, ששר שירים שאחרים כתבו לו. כשמלאו לו עשרים ואחת הוא דרש חוזה חדש, ששלט בו בעצמו, והתחיל לכתוב, לנגן ולהפיק כמעט הכול לבד, עם סינתסייזרים חדשים שגילה אז. Talking Book, שיצא באוקטובר 1972, היה האלבום השני בתקופה החדשה, ורבים רואים בו את תחילת רצף אלבומי המופת שלו.''',
'''הצליל מלא ועשיר: קלבינט פאנקי, סינתסייזר בס עמוק, פסנתר חשמלי, והקול של וונדר, שעובר מלחישה לצעקה של שמחה. Superstition נפתח בתופים ובריף קלבינט שכל העולם מכיר, והוא אחד משירי הפאנק הגדולים שנכתבו. You Are the Sunshine of My Life, שיר אהבה רך ושמח, הפך לסטנדרט שכולם שרים. ובין השניים יש בלדות יפהפיות, כמו You and I ו־Blame It on the Sun, על אהבה, על אובדן ועל תקווה. ג׳ף בק מנגן גיטרה בשיר אחד.''',
'''שני השירים הגדולים הגיעו למקום הראשון באמריקה, והאלבום הראה שאמן סול יכול להיות גם יוצר אלבומים שלם, כמו מרווין גיי ב־What's Going On (אלבום 207). וונדר המשיך מיד לאלבום הבא (אלבום 292), ובאמצע שנות השבעים היה כנראה המוזיקאי המוערך והמצליח ביותר בעולם. על העטיפה הוא מופיע בגלימה, עם שם האלבום בכתב ברייל.''',
'''שמעו את Superstition בקול רם, והקשיבו לכמה שכבות של קלבינט ותופים יש בו. ואז את You and I בשקט: רק וונדר, פסנתר וסינתסייזר, באחד משירי האהבה היפים שלו.''',
], [
('Superstition', 'ריף קלבינט מפורסם ותופים סוערים: אחד משירי הפאנק הגדולים.'),
('You Are the Sunshine of My Life', 'שיר אהבה רך ושמח שהפך לסטנדרט.'),
('You and I', 'בלדה יפהפייה עם פסנתר וסינתסייזר, בקול מלא רגש.'),
])

add(256, [
'''סטיבן סטילס, מבאפלו ספרינגפילד ומקרוסבי, סטילס, נאש ויאנג (אלבומים 80, 138 ו־183), היה מוזיקאי עם אנרגיה אינסופית, ואחרי שני אלבומי סולו (אלבום 181) הוא הקים להקה חדשה. הוא צירף את כריס הילמן, לשעבר מהבירדס ומהפליינג בוריטו ברדרס (אלבומים 57 ו־140), נגן פדל־סטיל, נגן כלי הקשה לטיני ומוזיקאים נוספים, וקרא לה "מנסס", על שם עיר בווירג׳יניה שבה התחולל קרב במלחמת האזרחים. האלבום הכפול הראשון שלהם יצא ב־1972.''',
'''סטילס חילק את האלבום לארבעה חלקים, אחד לכל צד של התקליטים, עם שמות: הראשון לטיני ורוקי, השני קאנטרי ובלוגראס, השלישי שירים שקטים ואישיים, והרביעי רוק ובלוז. יש כאן גיטרות אקוסטיות וחשמליות, פדל־סטיל, מנדולינה, קונגות והרמוניות של סטילס והילמן. It Doesn't Matter הוא שיר פופ רך עם מלודיה יפה, Johnny's Garden הוא שיר אקוסטי על מקום של שקט, ו־Bound to Fall הוא קאנטרי רוק מלא חן.''',
'''הלהקה הוציאה רק עוד אלבום אחד והתפרקה, ומנסס נשכח במידה רבה לעומת הלהקות הגדולות של סטילס. אבל רבים רואים בו את אלבום השיא שלו, ואחד האלבומים שמראים הכי טוב איך רוק, קאנטרי, בלוז ומוזיקה לטינית יכולים להתחבר בלי קושי.''',
'''שמעו את האלבום צד אחרי צד, כמו שסטילס תכנן, ושימו לב לשינוי באווירה בכל חלק. אם תבחרו רק שיר אחד, It Doesn't Matter הוא נקודת כניסה טובה.''',
], [
('It Doesn\'t Matter', 'שיר פופ רך עם מלודיה יפה והרמוניות של סטילס והילמן.'),
('Johnny\'s Garden', 'שיר אקוסטי ורגוע על מקום של שקט ומנוחה.'),
('Bound to Fall', 'קאנטרי רוק מלא חן, עם פדל־סטיל והרמוניות.'),
])

add(257, [
'''אחרי Electric Warrior (אלבום 238), מארק בולאן וטי רקס היו הלהקה הגדולה בבריטניה: בני נוער צרחו בהופעות, העיתונות דיברה על "טי־רקסטזה", ובולאן, עם תלתלים, נצנצים וגיטרה, היה אייקון הגלאם. The Slider יצא באמצע 1972, בשיא ההצלחה, והמפיק טוני ויסקונטי שוב עמד לצידו.''',
'''הנוסחה דומה לאלבום הקודם, והיא עובדת: ריפים פשוטים וקליטים של גיטרה, קצב רוקנרול מתנדנד, מיתרים של תזמורת שמוסיפים זוהר, והקול הלוחש והחושני של בולאן, ששר מילים מוזרות ומשעשעות שלא תמיד יש להן משמעות. Metal Guru, שנפתח בצעקה עליזה, ו־Telegram Sam היו שני להיטים שהגיעו למקום הראשון בבריטניה. Rock On ו־Buick Mackane מחוספסים וכבדים יותר, ו־Spaceball Ricochet הוא שיר רך ואקוסטי שמזכיר את ימי הפולק הקודמים של בולאן.''',
'''The Slider הצליח יפה גם באמריקה, אבל בבריטניה ההתלהבות מטי רקס התחילה לדעוך זמן קצר אחריו. בולאן נהרג בתאונת דרכים ב־1977, צעיר מאוד, אבל הגלאם שלו השפיע על דייוויד בואי (אלבום 266), על הפאנק שבא אחריו ועל להקות רבות עד היום.''',
'''שמעו את Metal Guru ואת Telegram Sam, ואז את Spaceball Ricochet, ותשמעו שני צדדים של בולאן: כוכב הרוק הזוהר והמשורר הקטן והשקט. אם אהבתם את Electric Warrior (אלבום 238), זה ההמשך הישיר.''',
], [
('Metal Guru', 'להיט שמח עם צעקה, ריף קליט ומיתרים זוהרים.'),
('Telegram Sam', 'ריף גיטרה פשוט ומדבק, וקול לוחש וחצוף.'),
('Spaceball Ricochet', 'שיר רך ואקוסטי, שמזכיר את בולאן של ימי הפולק.'),
])

add(258, [
'''דייוויד אקלס היה שחקן ילד בסרטים, ואחר כך כותב שירים שכמעט לא דומה לאף אחד בדורו: במקום רוק או פולק, הוא כתב שירים שנשמעים כמו מחזמר או כמו סיפורים קצרים, בהשראת קורט וייל ותיאטרון אמריקאי. אלטון ג׳ון וברני טאופין העריצו אותו, וטאופין אף הפיק את האלבום השלישי שלו, American Gothic, שהוקלט בלונדון עם תזמורת ויצא ב־1972.''',
'''השם לקוח מציור מפורסם של זוג איכרים אמריקאים חמורי סבר, והשירים הם דיוקנאות של אמריקה הקטנה: עיירות, כנסיות, משפחות וחיים שלא הלכו כמתוכנן. הקול של אקלס עמוק ומלא הבעה, כמו של שחקן על במה, והליווי נע בין פסנתר שקט לתזמורת מלאה ומקהלה. שיר הנושא פותח את האלבום בתמונה אירונית של זוג אמריקאי, ו־Montana Song ארוך במיוחד: יותר מעשר דקות על נסיעה לאדמה שבה חיו אבותיו, שנשמעות כמו מחזה שלם.''',
'''האלבום זכה לביקורות נלהבות, וכמה מבקרים השוו אותו לסרג׳נט פפר, אבל הוא כמעט לא נמכר, ואקלס הוציא רק עוד אלבום אחד ועזב את תעשיית המוזיקה ללימוד ולכתיבה. היום American Gothic נחשב לאוצר נשכח, ומי שמגלה אותו מתאהב בו. כותבים כמו אלביס קוסטלו וכותבי שירים רבים ציינו את אקלס כהשראה.''',
'''הקשיבו למילים, כמו שקוראים סיפור. התחילו בשיר הנושא, ואם הוא תופס אתכם, תנו ל־Montana Song את כל עשר הדקות שלו. אם אהבתם את רנדי ניומן (אלבום 240), תמצאו כאן אותה אמריקה, בצבעים כהים יותר.''',
], [
('American Gothic', 'שיר הנושא: דיוקן אירוני של זוג אמריקאי, עם פסנתר ותזמורת.'),
('Montana Song', 'יותר מעשר דקות של מסע לאדמת האבות, כמו מחזה שלם.'),
('Love\'s Enough', 'שיר אהבה פשוט ונוגע, שמראה את הצד הרך של אקלס.'),
])

add(259, [
'''האיגלס התחילו כלהקת הליווי של לינדה רונסטאדט בלוס אנג׳לס: גלן פריי ודון הנלי, שהפכו לכותבים הראשיים, ברני לידון, שבא מהפליינג בוריטו ברדרס (אלבום 140), ורנדי מייזנר. ב־1971 הם הפכו ללהקה עצמאית, נסעו ללונדון להקליט עם המפיק גלין ג׳ונס, שעבד עם הרולינג סטונס והלד זפלין, ואלבום הבכורה שלהם יצא ביוני 1972.''',
'''הצליל הוא קאנטרי רוק של קליפורניה: גיטרות אקוסטיות וחשמליות, בנג׳ו, והרמוניות קוליות של ארבעה זמרים שמתחברים כמו אחד. Take It Easy, שכתב ג׳קסון בראון יחד עם פריי, נפתח בגיטרה שמחה ומספר על נסיעה בכביש ועל ניסיון לא להתעצב, והפך לסמל של הלהקה. Witchy Woman של הנלי מסתורי וכהה יותר, עם תופים שבטיים, ו־Peaceful Easy Feeling הוא שיר רגוע ורך, כמו ערב במדבר.''',
'''שלושת השירים האלה הפכו ללהיטים, והאלבום פתח את דרכה של אחת הלהקות המצליחות בהיסטוריה. האיגלס לקחו את הרעיונות של הבירדס ושל הפליינג בוריטו ברדרס (אלבומים 133 ו־140) והפכו אותם לצליל מלוטש ונגיש שכבש את הרדיו האמריקאי, ובמשך שנות השבעים הם המשיכו לאלבומים ולהיטים גדולים עוד יותר.''',
'''שמעו את Take It Easy ואת Peaceful Easy Feeling בנסיעה, עם חלון פתוח. אחר כך השוו אותם לפליינג בוריטו ברדרס (אלבום 140), ותשמעו איך אותו סגנון נשמע מחוספס שם ומלוטש כאן.''',
], [
('Take It Easy', 'גיטרה שמחה, בנג׳ו והרמוניות: שיר הכביש הגדול של הלהקה.'),
('Witchy Woman', 'שיר כהה ומסתורי, עם תופים שבטיים וקול של דון הנלי.'),
('Peaceful Easy Feeling', 'שיר רגוע ורך, כמו ערב שקט במדבר.'),
])

add(260, [
'''טים באקלי התחיל כזמר פולק עדין (אלבומים 86 ו־160), ואחר כך יצא לניסויים של ג׳אז וקולות מוזרים שכמעט אף אחד לא קנה. ב־1972, אחרי כמה אלבומים שנכשלו, הוא החליט לשנות כיוון לגמרי ולהקליט אלבום של פאנק, רוק וסול, עם שירים על מין, על תשוקה ועל חיי הרחוב בלוס אנג׳לס. Greetings from L.A. יצא באוגוסט 1972.''',
'''זה באקלי הכי גופני ומזיע: גיטרות פאנקיות, בס עמוק, כלי נשיפה, מיתרים ותופים עם קצב של רחבת ריקודים. הקול שלו, שיכול לנוע על פני כמה אוקטבות, צועק, נאנח, לוחש ומתפתל, כאילו הוא מנסה להוציא מעצמו את כל מה שנשאר בפנים. Move with Me פותח ברוק מתגלגל, Get on Top הוא פאנק ארוך ומיוזע, ו־Sweet Surrender הוא בלדה ארוכה ומיוסרת, עם מיתרים דרמטיים, על אהבה שמשגעת. בכמה שירים המילים היו גלויות כל כך שתחנות רדיו לא הסכימו להשמיע אותם.''',
'''האלבום לא הצליח למכור הרבה, ובאקלי מת ממנת יתר ב־1975, בגיל עשרים ושמונה. במשך השנים האלבום הוערך מחדש, ורבים רואים בו אלבום אמיץ ומיוחד, שבו זמר פולק עדין מצא בתוכו זמר סול ופאנק. הקול שלו השפיע על זמרים רבים, וגם בנו, ג׳ף באקלי, הפך לזמר נערץ.''',
'''שמעו את Sweet Surrender, והקשיבו איך הקול של באקלי עולה ויורד מעל המיתרים. ואז השוו אותו לבאקלי העדין של Goodbye and Hello (אלבום 86): קשה להאמין שזה אותו אדם.''',
], [
('Sweet Surrender', 'בלדה מיוסרת ודרמטית, שבה הקול של באקלי נמתח לכל הכיוונים.'),
('Move with Me', 'הפותח: רוק מתגלגל ומיוזע עם כלי נשיפה.'),
('Get on Top', 'פאנק ארוך ומיוזע, שבו באקלי צועק, נאנח ומאלתר.'),
])

add(261, [
'''אחרי שני אלבומים שכמעט לא נמכרו (אלבומים 149 ו־190), ניק דרייק היה מדוכא, מסוגר ועייף מהופעות. בסוף 1971 הוא הגיע לאולפן בלונדון עם המהנדס ג׳ון ווד, ובשני לילות הקליט אלבום שלם: רק הקול שלו והגיטרה האקוסטית, ופסנתר אחד בשיר הנושא. בלי תזמורת, בלי להקה ובלי חברים. Pink Moon יצא בתחילת 1972, והוא נמשך פחות משלושים דקות.''',
'''הפשטות היא כל הסיפור. הגיטרה של דרייק, מכוונת בכיוונונים מיוחדים שהמציא לעצמו, נשמעת עשירה כמו תזמורת קטנה, והקול שלו שקט, קרוב וכמעט לוחש, כאילו הוא יושב לידכם בחדר. שיר הנושא, קצר ומסתורי, מדבר על "ירח ורוד" שבא לקחת את כולם. Place to Be הוא שיר עצוב ויפה על התבגרות ועל חולשה, Road ו־Things Behind the Sun מלאים בגיטרה מסובכת ובתחושה של בדידות, ו־From the Morning, השיר האחרון, נשמע פתאום אופטימי, כמו אור של בוקר.''',
'''גם האלבום הזה כמעט לא נמכר, ודרייק מת מנטילת יתר של תרופות נגד דיכאון ב־1974, בגיל עשרים ושש. הוא נשכח כמעט לגמרי, עד שבשנות התשעים הדור החדש גילה אותו, ובשנת 2000 שיר הנושא הופיע בפרסומת לפולקסווגן ופתאום נמכר יותר מאשר בכל שנות חייו. היום Pink Moon נחשב לאחת היצירות הכי אינטימיות ויפות במוזיקה הפופולרית.''',
'''שמעו את כל האלבום בבת אחת, בשקט, בלילה. הוא קצר מספיק. אחר כך השוו אותו ל־Bryter Layter (אלבום 190): אותו אדם, עם להקה ותזמורת, ועכשיו לבד לגמרי.''',
], [
('Pink Moon', 'שיר הנושא: קצר ומסתורי, עם גיטרה, קול ופסנתר אחד.'),
('Place to Be', 'שיר עצוב ויפה על התבגרות ועל חולשה.'),
('From the Morning', 'השיר האחרון, שנשמע פתאום אופטימי, כמו אור של בוקר.'),
])

add(262, [
'''אחרי Bridge Over Troubled Water (אלבום 196), סיימון וגרפונקל נפרדו. פול סיימון, שכתב את כל השירים של הצמד, רצה לגלות מי הוא לבד, ובאלבום הסולו הראשון שלו, שיצא בתחילת 1972, הוא יצא למסע של סגנונות: נסע לג׳מייקה כדי להקליט עם נגני רגאיי, ניגן עם נגני ג׳אז, בלוז ומוזיקה לטינית, ובחר ברוב השירים בצליל קטן ואינטימי.''',
'''Mother and Child Reunion, שהוקלט בקינגסטון, היה אחד משירי הרגאיי הראשונים שהגיעו לרדיו האמריקאי, הרבה לפני שבוב מארלי היה מוכר שם. Me and Julio Down by the Schoolyard הוא שיר קצבי ושמח, עם גיטרה אקוסטית, כלי הקשה לטיניים ושריקה, על שני חברים שעשו משהו אסור שלא ברור מהו. Duncan מספר, בליווי חלילים מאנדיים, על נער שעוזב את הבית, ו־Hobo's Blues הוא קטע קצר שבו סיימון מנגן עם הכנר הצרפתי הגדול סטפן גראפלי.''',
'''האלבום הצליח, ושני הלהיטים הראשונים הוכיחו שסיימון יכול להצליח גם בלי השותף שלו. יותר מזה, הוא הראה את הסקרנות של סיימון למוזיקה מכל העולם, הסקרנות שתוביל אותו כעבור יותר מעשור לאלבום Graceland, שהוקלט עם מוזיקאים מדרום אפריקה.''',
'''שמעו את Mother and Child Reunion ואחריו את Me and Julio, שני שירים שמחים עם מילים עצובות או מסתוריות. אחר כך שמעו את Duncan, ונסו לדמיין אותו בקולם של סיימון וגרפונקל (אלבומים 71, 125 ו־196).''',
], [
('Mother and Child Reunion', 'רגאיי שהוקלט בג׳מייקה: מהראשונים שהגיעו לרדיו האמריקאי.'),
('Me and Julio Down by the Schoolyard', 'שיר קצבי ושמח עם גיטרה, כלי הקשה ושריקה.'),
('Duncan', 'סיפור על נער שעוזב את הבית, בליווי חלילים מהאנדים.'),
])

add(263, [
'''בריאן פרי, בן של כורה מצפון אנגליה שלמד אמנות, הקים בלונדון להקה שנראתה ונשמעה כמו אף אחת אחרת: הוא עצמו בחליפות של כוכב קולנוע משנות החמישים, אנדי מקיי בסקסופון ובאבוב, פיל מנזנרה בגיטרה, והכי מוזר, בריאן אינו, שלא ניגן על כלי רגיל אלא על סינתסייזר ומכשירי הקלטה, ושינה את הצלילים של כל השאר. אלבום הבכורה שלהם יצא ביוני 1972, בהפקת פיט סינפילד, התמלילן של קינג קרימזון (אלבום 167).''',
'''זה אלבום שמערבב רוקנרול של שנות החמישים, זוהר של הוליווד, אוונגרד ומדע בדיוני. Re-Make/Re-Model פותח בקולות של מסיבה, ואז הלהקה מתפרצת ברוק פרוע, שבו כל כלי מקבל רגע סולו קצר ומטורף. Ladytron נפתח בצלילים חלליים של אינו ומתפתח לשיר דרמטי, ו־2HB הוא מחווה רכה לשחקן המפורסם המפרי בוגארט. פרי שר בקול רוטט ותיאטרלי, כמו זמר קברט מעולם אחר.''',
'''רוקסי מיוזיק הפכו מיד לכוכבים בבריטניה, והם השפיעו על הגלאם, על הפאנק ועל הניו וייב שבאו אחריהם, מדייוויד בואי ועד דוראן דוראן. אינו עזב אחרי האלבום השני (אלבום 282) לקריירת סולו מיוחדת (אלבום 300), ופרי הוביל את הלהקה לצליל מלוטש ורומנטי יותר.''',
'''שמעו את Re-Make/Re-Model ונסו לזהות את כל הסולואים הקצרים לקראת הסוף. ואז את Ladytron, והקשיבו לצלילים המוזרים שאינו מוסיף ברקע.''',
], [
('Re-Make/Re-Model', 'הפותח: מסיבה, רוק פרוע וסולואים קצרים ומטורפים.'),
('Ladytron', 'צלילים חלליים של אינו שמתפתחים לשיר דרמטי.'),
('2HB', 'מחווה רכה לשחקן המפרי בוגארט, עם סקסופון חולם.'),
])

add(264, [
'''אליס קופר היה בתחילת שנות השבעים שם של להקה, לא רק של הזמר שלה, וינס פורנייה, שהפך לאליס. הם היו להקת רוק מדטרויט שהבינה, לפני רבים אחרים, שרוק יכול להיות גם תיאטרון: איפור שחור, נחשים, גיליוטינות על הבמה והרבה הומור שחור. School's Out, האלבום החמישי שלהם, יצא באמצע 1972, בהפקת בוב אזרין, והעטיפה המקורית נראתה כמו שולחן בית ספר ישן, שנפתח.''',
'''שיר הנושא הוא ההמנון של כל תלמיד ביום האחרון של השנה: ריף גיטרה פשוט ופרוע, מקהלת ילדים וצעקה של שחרור, "בית הספר נגמר לתמיד". שאר האלבום מפתיע: הלהקה מתאהבת בברודווי, ו־Gutter Cat vs. the Jets מצטט את "סיפור הפרברים", על כנופיות רחוב. Blue Turk הוא ג׳אז רוק איטי עם כלי נשיפה, My Stars דרמטי ותיאטרלי, ו־Alma Mater הוא פרידה רכה ומשעשעת מחברים לספסל הלימודים.''',
'''שיר הנושא הגיע למקום הראשון בבריטניה ולעשירייה הראשונה באמריקה, והפך לשיר שמשמיעים בכל סוף שנת לימודים. האלבום הראה שרוק כבד יכול להיות גם מצחיק, דרמטי ומלא סיפורים, והשפיע על להקות הרוק והמטאל התיאטרליות שבאו אחריו. הלהקה המשיכה לאלבום מצליח עוד יותר (אלבום 296).''',
'''שמעו את שיר הנושא בקול רם, ואז את Gutter Cat vs. the Jets, ונסו לזהות את המנגינות מ"סיפור הפרברים".''',
], [
('School\'s Out', 'ההמנון של היום האחרון בבית הספר: ריף פרוע וצעקת שחרור.'),
('Gutter Cat vs. the Jets', 'כנופיות רחוב וציטוטים מ"סיפור הפרברים".'),
('Alma Mater', 'פרידה רכה ומשעשעת מבית הספר ומהחברים.'),
])

add(265, [
'''הטמפטיישנס, קבוצת הקולות המפורסמת של מוטאון, עברו בסוף שנות השישים לסול פסיכדלי עם המפיק נורמן ויטפילד (אלבום 158). ויטפילד רצה יותר ויותר מקום לכלים ולאווירה, וזה יצר מתח עם הזמרים, שרצו לשיר. All Directions יצא ביולי 1972, בתקופה שבה הרכב הקבוצה השתנה, ודניס אדוארדס היה הקול המוביל.''',
'''הלב של האלבום הוא Papa Was a Rollin' Stone: כמעט שתים־עשרה דקות שנפתחות בקו בס אחד, כפיים וכינורות, ורק אחרי כמעט ארבע דקות מגיע הקול הראשון. ארבעת הזמרים מספרים, אחד אחרי השני, על אב שהלך ולא חזר, והילדים שמגלים מי הוא היה רק אחרי מותו. באלבום יש גם פאנק שמח כמו Funky Music Sho Nuff Turns Me On, ובלדה רכה ויפה, The First Time Ever (I Saw Your Face), שיר של יואן מקול.''',
'''Papa Was a Rollin' Stone הגיע, בגרסה מקוצרת, למקום הראשון באמריקה, וזכה בשלושה פרסי גראמי. הוא נחשב לאחד השירים הגדולים של הסול ולאחד הרגעים שבהם אולפן ההקלטה עצמו הפך לכלי. הבס, התזמורת והקצב האיטי והמאיים השפיעו על מוזיקת הדיסקו, ההיפ הופ והמוזיקה האלקטרונית שבאה אחריו.''',
'''תנו ל־Papa Was a Rollin' Stone את כל שתים־עשרה הדקות. הקשיבו איך כל כלי נכנס בתורו: בס, כפיים, חצוצרה, כינורות, ואז הקולות.''',
], [
('Papa Was a Rollin\' Stone', 'שתים־עשרה דקות של בס, כינורות וסיפור על אב שהלך.'),
('Funky Music Sho Nuff Turns Me On', 'פאנק שמח וקצבי, עם קולות שמתחלפים.'),
('The First Time Ever (I Saw Your Face)', 'בלדה רכה ויפה על אהבה ממבט ראשון.'),
])

add(266, [
'''בתחילת 1972 דייוויד בואי המציא דמות: זיגי סטארדאסט, כוכב רוק מהחלל שמגיע לכדור הארץ חמש שנים לפני סוף העולם, הופך לאליל, ונהרס בגלל התהילה והעודפים. עם להקת "העכבישים ממאדים", והגיטריסט מיק רונסון בראשה, בואי הקליט את האלבום והופיע בתור זיגי: שיער אדום, בגדים צבעוניים ואיפור. The Rise and Fall of Ziggy Stardust יצא ביוני 1972.''',
'''Five Years פותח לאט, בתופים ובתיאור עצוב של עולם שנשארו לו חמש שנים, ונבנה לצעקה. Starman הוא שיר פופ שמח על חייזר שרוצה לפגוש את הילדים, Moonage Daydream ו־Suffragette City הם רוק כבד וסוער עם גיטרות של רונסון, ושיר הנושא מספר את כל הסיפור בקצרה. בסוף, Rock 'n' Roll Suicide נבנה מגיטרה אקוסטית לתזמורת ולצעקה: "אתה לא לבד".''',
'''ההופעה של בואי עם Starman בטלוויזיה הבריטית, כשהוא מניח יד על הכתף של רונסון, הפכה לרגע מכונן שכמעט כל מוזיקאי בריטי בדור ההוא זוכר. האלבום הפך את בואי לכוכב, ובקיץ 1973 הוא "הרג" את זיגי בהופעה בלונדון, מול קהל המום. Ziggy Stardust נחשב לאחד האלבומים החשובים של הרוק, והרעיון של כוכב שממציא לעצמו דמות השפיע על אמנים רבים.''',
'''שמעו את האלבום מההתחלה עד הסוף, כמו סיפור. התחילו ב־Five Years ותגיעו עד Rock 'n' Roll Suicide. אם אהבתם את Hunky Dory (אלבום 239), תשמעו כאן את אותו כותב, עם להקת רוק חזקה.''',
], [
('Starman', 'שיר פופ שמח על חייזר שרוצה לפגוש את הילדים.'),
('Five Years', 'הפותח: תופים, תיאור של עולם שנשארו לו חמש שנים, וצעקה.'),
('Ziggy Stardust', 'שיר הנושא: כל הסיפור של הכוכב, עם ריף מפורסם של רונסון.'),
])

add(267, [
'''וור הייתה להקה מלוס אנג׳לס עם נגנים שחורים, לבנים ולטינים, והם התחילו כלהקת הליווי של אריק ברדון מהאנימלס. אחרי שברדון עזב, הם המשיכו לבד, עם צליל שחיבר פאנק, סול, ג׳אז, רוק ומוזיקה לטינית, ועם מפוחית של לי אוסקר מדנמרק. The World Is a Ghetto, האלבום החמישי שלהם, יצא בסוף 1972.''',
'''זו מוזיקה רגועה, חמה וגרובית, שלא ממהרת לשום מקום. The Cisco Kid הוא שיר קצבי ומשעשע על גיבור מערבונים מקסיקני, עם כלי הקשה, כלי נשיפה ומפוחית. שיר הנושא נמשך כעשר דקות: קצב איטי, פסנתר חשמלי, סקסופון ושירה נוגה על עוני ועל חיים ברחובות העיר, שמתפתחים לג׳אם ארוך. City, Country, City הוא קטע אינסטרומנטלי של יותר משתים־עשרה דקות, שעובר מאווירה עירונית עמוסה לנוף כפרי שקט וחוזר.''',
'''האלבום הגיע למקום הראשון באמריקה, והיה לפי בילבורד האלבום הנמכר ביותר של 1973, לפני אלבומים של סטיבי וונדר (אלבום 255) ואחרים. הלהקה הראתה שמוזיקה שמחברת בין תרבויות יכולה להגיע לקהל הגדול, והשירים שלה נדגמו אחר כך רבות בהיפ הופ.''',
'''זה אלבום שמתאים לנסיעה ארוכה או לערב קיץ חם. התחילו ב־The Cisco Kid, ואז תנו לשיר הנושא ולקטעים הארוכים לזרום, בלי למהר.''',
], [
('The Cisco Kid', 'שיר קצבי ומשעשע עם מפוחית, כלי נשיפה וכלי הקשה.'),
('The World Is a Ghetto', 'עשר דקות איטיות ונוגות על חיים ברחובות העיר.'),
('City, Country, City', 'מסע אינסטרומנטלי ארוך מהעיר העמוסה לנוף הכפרי וחזרה.'),
])

add(268, [
'''אל גרין, זמר צעיר מארקנסו שגדל על גוספל, הגיע לממפיס ופגש את המפיק וילי מיטשל מחברת היי רקורדס. מיטשל שמע את קולו הגבוה והרך, ושכנע אותו לא לצעוק כמו זמרי הסול האחרים אלא לשיר בשקט, כמעט בלחישה. יחד עם להקת האולפן של היי, והמתופף אל ג׳קסון מבוקר טי והאם. ג׳י. אס (אלבום 32), הם יצרו צליל חדש. Let's Stay Together יצא בתחילת 1972.''',
'''הצליל של האלבום רך, חם ומדויק: תופים עדינים ויציבים, אורגן, בס עגול, כלי נשיפה שקטים ומיתרים, והקול של גרין, שזז בחופשיות מעל הכול, עולה לפלסטו ויורד לגניחה. שיר הנושא, בקשה פשוטה לאהבה שתימשך, הפך לאחד משירי האהבה הגדולים של הסול. יש כאן גם גרסה איטית ויפהפייה ל־How Can You Mend a Broken Heart של הבי ג׳יז (שנמצא גם באלבום 209), שנמתחת לשש דקות, ו־La-La for You ו־What Is This Feeling הם שירי אהבה עדינים ומלאי חן.''',
'''שיר הנושא הגיע למקום הראשון באמריקה והפך את גרין לכוכב, והוא המשיך להוציא להיטים רבים באותו צליל. כעבור כמה שנים הוא חזר לכנסייה והפך לכומר. הצליל של גרין ומיטשל השפיע על זמרי סול ו־R&B רבים, ושיר הנושא נשמע עד היום בחתונות, בסרטים ואפילו בפי נשיאים.''',
'''שמעו את שיר הנושא בשקט, והקשיבו לתופים: יציבים וכמעט מינימליים, ובכל זאת הם מחזיקים את השיר. אחר כך השוו את How Can You Mend a Broken Heart לגרסה של הבי ג׳יז (אלבום 209).''',
], [
('Let\'s Stay Together', 'שיר האהבה הגדול: תופים רכים, כלי נשיפה וקול לוחש.'),
('How Can You Mend a Broken Heart', 'גרסה איטית ויפהפייה לשיר של הבי ג׳יז.'),
('La-La for You', 'שיר אהבה עדין ומלא חן, עם פלסטו רך.'),
])

add(269, [
'''ב־1971, בגלל חובות מס עצומים, הרולינג סטונס עזבו את בריטניה ועברו לדרום צרפת. קית׳ ריצ׳רדס שכר וילה גדולה ליד הים, והלהקה הקליטה במרתף החם והלח שלה, עם אולפן נייד שחונה בחוץ, בין מסיבות, אורחים, סמים וחוסר סדר. ההקלטות הושלמו בלוס אנג׳לס, ו־Exile on Main St., אלבום כפול, יצא במאי 1972.''',
'''הצליל עמום, דחוס ומבולגן, כאילו הלהקה מנגנת בחדר צפוף מלא עשן, והקול של מיק ג׳אגר קבור לפעמים בתוך הגיטרות. יש כאן רוקנרול מהיר כמו Rocks Off ו־Rip This Joint, קאנטרי כמו Sweet Virginia, בלוז כבד כמו Ventilator Blues, וגוספל כמו Shine a Light ו־Let It Loose, עם מקהלות ופסנתר. Tumbling Dice, הלהיט, הוא שיר מתנדנד על הימורים ואהבה, ו־Happy, שקית׳ ריצ׳רדס שר, הוא רוק שמח ופשוט.''',
'''המבקרים היו מבולבלים בהתחלה, ורבים חשבו שהאלבום ארוך מדי ולא ברור. עם השנים הוא הפך בעיני רבים לאלבום הגדול ביותר של הסטונס, ולסיכום של כל מה שהם אהבו במוזיקה האמריקאית: בלוז, קאנטרי, סול וגוספל. הוא סוגר את רצף האלבומים הגדולים שלהם (אלבומים 107, 148 ו־214).''',
'''זה אלבום שכדאי לשמוע כמה פעמים עד שהוא נפתח. התחילו ב־Tumbling Dice, Happy ו־Shine a Light, ואז שמעו את הכול ברצף, בקול רם.''',
], [
('Tumbling Dice', 'הלהיט: רוק מתנדנד על הימורים ועל אהבה, עם מקהלה.'),
('Happy', 'רוק שמח ופשוט, בקולו של קית׳ ריצ׳רדס.'),
('Shine a Light', 'שיר גוספל עם פסנתר ומקהלה, מהרגעים היפים של הסטונס.'),
])

add(270, [
'''לינירד סקינירד הגיעו מג׳קסונוויל שבפלורידה, והשם שלהם הוא עקיצה למורה להתעמלות, לאונרד סקינר, שהעניש את חברי הלהקה על השיער הארוך שלהם. הם ניגנו שנים בברים של הדרום, עם שלוש גיטרות חשמליות, עד שהמוזיקאי אל קופר, שניגן עם בוב דילן (אלבום 58), גילה אותם, החתים אותם והפיק את אלבום הבכורה שלהם, שיצא ב־1973. השם של האלבום הוא פשוט הדרך לבטא את שם הלהקה.''',
'''זה רוק דרומי: בלוז, קאנטרי ורוק כבד, עם שלוש גיטרות שמתחלפות בסולואים, פסנתר, והקול של רוני ואן זנט, מחוספס ופשוט. Gimme Three Steps הוא שיר מצחיק על בחור שמנסה לברוח מבעל קנאי, Simple Man הוא שיר איטי ורציני, שבו אמא נותנת לבנה עצות לחיים, ו־Tuesday's Gone שיר פרידה נוגה. וסוגר את האלבום Free Bird: בלדה על אדם שלא יכול להישאר במקום אחד, שמתחילה באורגן ובגיטרת סלייד ומסתיימת בכמה דקות של סולואים דוהרים.''',
'''Free Bird הפך לאחד משירי הרוק המפורסמים בעולם, ולשיר שקהל מבקש בכל הופעה. הלהקה הפכה לאחת הגדולות באמריקה, עד שב־1977 מטוס שהטיס אותם להופעה התרסק, ורוני ואן זנט ועוד שניים מחברי הלהקה נהרגו. האלבום הזה נשאר המסמך של להקה צעירה, רעבה וכנה.''',
'''שמעו את Free Bird עד הסוף, ושימו לב לרגע שבו הבלדה הופכת לדהירה. אם אהבתם את האולמן ברדרס (אלבום 213), תשמעו כאן את אותו דרום, בגרסה פשוטה ומחוספסת יותר.''',
], [
('Free Bird', 'בלדה שהופכת לכמה דקות של סולואים דוהרים.'),
('Simple Man', 'שיר איטי ורציני על עצות של אמא לבנה.'),
('Gimme Three Steps', 'שיר מצחיק על בחור שמנסה לברוח מבעל קנאי.'),
])

add(271, [
'''מייקל ויינר, מנהל בחברת תקליטים בלוס אנג׳לס, היה צריך מוזיקה לסרט אימה זול מ־1972 על אדם עם שני ראשים. הוא אסף קבוצה של נגני אולפן, עם נגן הבונגו קינג אריסון בחזית, והקליט כמה קטעים קצביים. אחד מהם הצליח ברדיו, וכך נולדה "להקת הבונגו המדהימה", להקה שלא הייתה באמת להקה. Bongo Rock, האלבום הראשון שלהם, יצא ב־1973.''',
'''זה אלבום של גרסאות כיסוי אינסטרומנטליות לשירי רוק ופופ מוכרים, עם הרבה בונגו, קונגות ותופים, כלי נשיפה, אורגן וגיטרה. יש כאן גרסה ל־In-A-Gadda-Da-Vida של איירון באטרפליי (אלבום 123), עם סולו תופים ארוך, ושיר הנושא, גרסה חדשה ללהיט בונגו משנות החמישים. אבל הקטע החשוב הוא Apache, גרסה לשיר של להקת השאדואוז הבריטית: מלודיה של מערבון, ובאמצע, כמעט דקה שבה נשארים רק התופים והבונגו.''',
'''בתחילה זה היה עוד תקליט חביב ונשכח. אבל בברונקס של אמצע שנות השבעים, התקליטן קול הרק שם לב שהקהל משתגע בדיוק ברגעים שבהם נשארים רק התופים, ה"ברייק". הוא לקח שני עותקים של התקליט והחליף ביניהם כדי למתוח את הרגע הזה לדקות ארוכות, וכך, יחד עם שירים נוספים, נולדו ההיפ הופ והברייקדאנס. Apache נחשב לאחד הקטעים שנדגמו הכי הרבה בהיסטוריה, והוא נשמע בעשרות שירי היפ הופ.''',
'''שמעו את Apache, וחכו לרגע שבו כל הכלים נעלמים ונשארים רק התופים. זה הרגע ששינה את ההיסטוריה. אחר כך השוו את In-A-Gadda-Da-Vida למקור (אלבום 123).''',
], [
('Apache', 'מלודיה של מערבון וברייק תופים שממנו נולד ההיפ הופ.'),
('Bongo Rock \'73', 'שיר הנושא: להיט בונגו ישן בגרסה חדשה וקצבית.'),
('In-A-Gadda-Da-Vida', 'גרסה אינסטרומנטלית לשיר של איירון באטרפליי, עם סולו תופים.'),
])

add(272, [
'''אחרי ההצלחה של Ziggy Stardust (אלבום 266), דייוויד בואי יצא לסיבוב הופעות ראשון באמריקה, וכתב את רוב השירים של האלבום הבא בדרכים: באוטובוסים, ברכבות ובחדרי מלון, בין לוס אנג׳לס, דטרויט וניו יורק. הוא עצמו תיאר את האלבום כ"זיגי נוסע לאמריקה". Aladdin Sane יצא באפריל 1973, עם עטיפה מפורסמת: בואי עם ברק אדום וכחול מצויר על הפנים.''',
'''הלהקה אותה להקה, עם הגיטרה של מיק רונסון, אבל נוסף לה הפסנתרן מייק גרסון, נגן ג׳אז שמכניס לשירים צלילים פרועים ומפתיעים. בשיר הנושא הוא מנגן סולו פסנתר אוונגרדי ומטורף, שנשמע כאילו הפסנתר מתפרק. The Jean Genie הוא רוק בלוז עם ריף פשוט ומוכר, Panic in Detroit מלא בתופים ובמתח עירוני, ו־Drive-In Saturday הוא שיר נוסטלגי ורך על עתיד שבו אנשים שכחו איך מתאהבים. Time דרמטי ותיאטרלי, כמו קברט, ו־Lady Grinning Soul סוגר בבלדה רומנטית ויפה.''',
'''Aladdin Sane הגיע למקום הראשון בבריטניה, וההזמנות מראש היו גדולות מכל אלבום מאז הביטלס. הוא מתעד את בואי בשיא הגלאם, מתוח, עייף ומלא רעיונות, והעטיפה עם הברק הפכה לאחת התמונות המפורסמות של הרוק. כמה חודשים אחר כך בואי פירק את להקת זיגי.''',
'''שמעו את שיר הנושא והקשיבו לסולו הפסנתר של גרסון. אחר כך את The Jean Genie, ואחריו את Let's Spend the Night Together, גרסה מהירה ופרועה לשיר של הרולינג סטונס.''',
], [
('The Jean Genie', 'רוק בלוז עם ריף פשוט ומוכר ואנרגיה של רחוב.'),
('Aladdin Sane', 'שיר הנושא, עם סולו פסנתר פרוע ומטורף של מייק גרסון.'),
('Drive-In Saturday', 'שיר נוסטלגי ורך על עתיד שבו אנשים שכחו איך לאהוב.'),
])

add(273, [
'''רוברט פריפ, מנהיג קינג קרימזון (אלבום 167), החליף את כל חברי הלהקה סביבו, ובסוף 1972 הרכיב הרכב חדש לגמרי: הבסיסט והזמר ג׳ון וטון, המתופף ביל ברופורד, שעזב את יס מיד אחרי Close to the Edge (אלבום 249), הכנר דייוויד קרוס, ונגן כלי ההקשה ג׳יימי מיור, שהביא לבמה פעמונים, שרשראות, צעצועים ומסורים. Larks' Tongues in Aspic יצא במרץ 1973.''',
'''השם, "לשונות עפרוני בג׳לי", נשמע כמו מנה מוזרה, והמוזיקה מתאימה: קטעים ארוכים ואינסטרומנטליים, שעוברים מרגעים שקטים ושבירים של כינור ופעמונים לפרצים כבדים ואלימים של גיטרה, בס ותופים. החלק הראשון של שיר הנושא נפתח בצלילים עדינים ומגיע לסערה, והחלק השני, שסוגר את האלבום, בנוי על ריף גיטרה חד ומסובך שנשמע כמו מטאל. ביניהם יש שירים: Book of Saturday שקט ועדין, Easy Money מתגלגל ומאיים, ו־The Talking Drum בונה מתח לאט לאט, מלחישה לשיא.''',
'''ג׳יימי מיור עזב זמן קצר אחרי ההקלטות והלך לחיות במנזר בודהיסטי, אבל ההרכב הזה של קינג קרימזון הקליט עוד שני אלבומים חשובים. Larks' Tongues in Aspic השפיע רבות על הרוק המתקדם, על מטאל ועל רוק ניסיוני, והוא מראה צד קשוח, מאלתר ומפחיד יותר של הפרוג.''',
'''שמעו את The Talking Drum ואחריו, בלי הפסקה, את החלק השני של שיר הנושא, כמו שהם מופיעים בתקליט: השקט הופך לסערה. באוזניות, בקול רם.''',
], [
('Larks\' Tongues in Aspic, Part Two', 'ריף גיטרה חד ומסובך שנשמע כמעט כמו מטאל.'),
('The Talking Drum', 'מתח שנבנה לאט, מלחישה של תופים לשיא.'),
('Book of Saturday', 'שיר קצר, שקט ועדין בין הסערות.'),
])

add(274, [
'''הוויילרס, בוב מארלי, פיטר טוש ובאני ויילר, שרו יחד בג׳מייקה כבר מתחילת שנות השישים והוציאו שם הרבה להיטים, אבל מחוץ לאי כמעט אף אחד לא הכיר אותם. ב־1972 הם פגשו את כריס בלקוול, בעלי חברת איילנד בלונדון, שהחליט להפוך אותם לכוכבים כמו להקת רוק: הם הקליטו בקינגסטון, ובלקוול הוסיף בלונדון גיטרה וקלידים של נגני רוק, כדי שהצליל יתאים לקהל שגדל על הנדריקס ועל הרולינג סטונס. Catch a Fire יצא באפריל 1973, והעטיפה הראשונה שלו הייתה בצורת מצית.''',
'''זה רגאיי, עם בס עמוק ועגול, גיטרה שמנגנת על הפעמה ה"לא נכונה", אורגן מתנדנד, והקולות של השלושה, שמתחברים כמו בגוספל. אבל המילים רחוקות מלהיות שמחות: Concrete Jungle מתאר חיים בשכונות העוני של קינגסטון, Slave Driver ו־400 Years מדברים על העבדות ועל הדרך שבה ההיסטוריה ממשיכה לפגוע, ו־Stir It Up, שיר אהבה רך ומפתה, מראה את הצד המלודי של מארלי.''',
'''האלבום לא נמכר הרבה בהתחלה, אבל המבקרים התלהבו, והוא פתח לרגאיי את הדרך לעולם. כעבור שנה טוש ובאני עזבו, ומארלי הפך לכוכב העולמי הראשון מהעולם השלישי, ולסמל של חופש ושל גאווה. רגע לפני כן, פול סיימון הקליט את אחד משירי הרגאיי הראשונים שהגיעו לרדיו האמריקאי (אלבום 262).''',
'''שמעו את Concrete Jungle, והקשיבו לסולו הגיטרה הרוקי שהוסף בלונדון. ואז את Stir It Up, ותשמעו למה העולם התאהב במארלי.''',
], [
('Concrete Jungle', 'הפותח: בס עמוק ותיאור של חיים בשכונות העוני.'),
('Stir It Up', 'שיר אהבה רך ומפתה, מהמלודיים של מארלי.'),
('Slave Driver', 'רגאיי מתנדנד עם מילים על העבדות ועל הדיכוי.'),
])

add(275, [
'''הוקווינד הייתה להקה מלונדון שניגנה בחינם בפסטיבלים, בהופעות צדקה ומתחת לגשרים, עם דמיון שלם של חלליות, מדע בדיוני ומסעות בזמן. בחורף 1972 הם יצאו לסיבוב הופעות עם מופע שלם שנקרא "הטקס החללי": אורות מהבהבים, רקדנית, משורר שמקריא טקסטים על החלל, ולהקה שמנגנת בלי הפסקה. האלבום הכפול Space Ritual, שהוקלט בהופעות בליברפול ובלונדון, יצא ב־1973.''',
'''המוזיקה פשוטה וכבדה: ריפי גיטרה שחוזרים שוב ושוב, בס רועם של לֶמִי, שהקים אחר כך את מוטורהד, תופים עקשניים, וסינתסייזרים ומכשירים אלקטרוניים שיוצרים רעשים של חלליות, רוחות ואזעקות. בין השירים יש הקראות של שירה, כמו Sonic Attack, הוראות מאיימות למקרה של מתקפה קולית. Born to Go ו־Master of the Universe דוהרים ומהפנטים, ו־Orgone Accumulator הוא ג׳אם ארוך ומסחרר. הכול זורם מקטע לקטע, כמו מסע אחד ארוך.''',
'''Space Ritual נחשב לאחד מאלבומי ההופעה החשובים של הרוק הפסיכדלי, והוא השפיע על הפאנק, על המטאל ועל ה"ספייס רוק", כי הראה שאפשר ליצור מסע גדול עם כמה אקורדים פשוטים ועם הרבה רעש. הלהקה, עם הרבה חילופי הרכב, ממשיכה להופיע עד היום.''',
'''זה לא אלבום לשמוע שיר אחרי שיר. שימו אותו ברקע, בקול רם, בחדר חשוך, ותנו לו לזרום. אם אהבתם את Tago Mago של קאן (אלבום 219), זה צד אחר של אותה חזרתיות מהפנטת.''',
], [
('Born to Go', 'ריף דוהר ומהפנט שפותח את המסע.'),
('Master of the Universe', 'רוק כבד וחללי, עם בס רועם ורעשי חלליות.'),
('Orgone Accumulator', 'ג׳אם ארוך ומסחרר, שלא מפסיק לנוע.'),
])

add(276, [
'''ג׳ון קייל, מוזיקאי מוויילס שלמד מוזיקה קלאסית, היה החבר הניסיוני של הוולווט אנדרגראונד (אלבומים 91 ו־104): הוא ניגן בוויולה חשמלית רועשת והביא רעיונות של אוונגרד. אחרי שעזב, הוא הפיק אלבומים של אחרים, בהם של הסטוג׳ס (אלבום 171) ושל ניקו. ב־1973 הוא הוציא את Paris 1919, אלבום שמפתיע דווקא ביופי ובעדינות שלו, עם מוזיקאים מלהקת ליטל פיט ותזמורת.''',
'''השירים מלודיים ורכים, עם פסנתר, גיטרות, מיתרים וקול עמוק וחם, והמילים מלאות בהיסטוריה, בספרות ובזיכרונות. Child's Christmas in Wales פותח בזיכרונות של חג המולד בילדות, בהשראת סיפור של המשורר הוולשי דילן תומס, עם גיטרת סלייד של לואל ג׳ורג׳. שיר הנושא, עם תזמורת, מתייחס לוועידת השלום בפריז אחרי מלחמת העולם הראשונה, Graham Greene הוא שיר עליז ומשעשע על הסופר הבריטי, ו־Andalucia הוא שיר אהבה שקט ויפהפה.''',
'''האלבום לא הצליח הרבה בזמנו, אבל עם השנים הוא הפך לאחד האהובים של קייל, ולדוגמה לאיך מוזיקאי אוונגרד יכול לכתוב שירי פופ יפים. קייל המשיך לקריירה ארוכה ומגוונת, והפיק עוד אלבומים חשובים של אחרים.''',
'''שמעו את Child's Christmas in Wales ואחריו את Andalucia, ואז דמיינו את אותו אדם מנגן את הוויולה הצורמת של הוולווט (אלבום 104). קשה להאמין שזה אותו מוזיקאי.''',
], [
('Child\'s Christmas in Wales', 'זיכרונות ילדות של חג, עם גיטרת סלייד ופסנתר.'),
('Andalucia', 'שיר אהבה שקט ויפהפה, בקול עמוק וחם.'),
('Paris 1919', 'שיר הנושא: תזמורת, קצב מהיר והיסטוריה אירופית.'),
])

add(277, [
'''קאן, הלהקה הניסיונית מקלן (אלבום 219), הקליטה את Future Days ב־1973 באולפן שלה, בית קולנוע ישן ליד העיר. זה היה האלבום האחרון עם הזמר היפני דאמו סוזוקי, שעזב זמן קצר אחר כך, התחתן והתרחק מהמוזיקה לכמה שנים. במקום הרעש והאינטנסיביות של האלבומים הקודמים, הלהקה יצרה כאן משהו רך, זורם ושקט.''',
'''באלבום רק ארבעה קטעים, וכולם ארוכים. שיר הנושא נפתח ברעשי רקע ובמים, ואז נכנסים תופים עדינים ומדויקים של יאקי ליבצייט, בס רך וקולו של סוזוקי, שלוחש יותר משהוא שר, כמו בחלום. Spray מאלתר ונודד, Moonshake הוא שיר פופ קצר וקצבי, ו־Bel Air, בן עשרים דקות, ממלא צד שלם ונשמע כמו נסיעה ארוכה ברכב, בנוף שמשתנה לאט. הכלים לא מתחרים זה בזה, אלא זורמים יחד.''',
'''Future Days נחשב לאחד האלבומים היפים של קאן ושל הקראוטרוק, והוא נשמע כמו הקדמה למוזיקת האמביינט שבריאן אינו יפתח בהמשך (אלבום 300). הרבה להקות רוק אלטרנטיבי ואלקטרוני הושפעו מהצליל השקט והמתגלגל שלו.''',
'''זה אלבום לשעת ערב רגועה או לנסיעה ארוכה. אל תקשיבו לו בריכוז, תנו לו להיות ברקע ותראו איך הוא לאט לאט ממלא את החדר. השוו את השקט כאן לכאוס של Tago Mago (אלבום 219).''',
], [
('Future Days', 'שיר הנושא: מים, תופים עדינים וקול לוחש כמו בחלום.'),
('Moonshake', 'שיר פופ קצר וקצבי, עם תופים מדויקים ובס.'),
('Bel Air', 'עשרים דקות של נסיעה ארוכה בנוף שמשתנה לאט.'),
])

add(278, [
'''אחרי ההצלחה של Transformer (אלבום 250), כולם ציפו מלו ריד ללהיטים נוספים. במקום זה, הוא הקליט עם המפיק בוב אזרין, שעבד עם אליס קופר (אלבום 264), אלבום קודר ועצוב במיוחד: סיפור של זוג אמריקאים, ג׳ים וקרוליין, שחיים בברלין המחולקת, בין סמים, אלימות, קנאה ואובדן. Berlin יצא ב־1973, עם תזמורת, מקהלה ונגנים כמו ג׳ק ברוס מקרים וסטיב ווינווד מטראפיק.''',
'''המוזיקה יפה והמילים קשות מאוד. שיר הנושא פותח בפסנתר של בר ושיר אהבה רך, Caroline Says מתאר את היחסים המתפרקים, ו־How Do You Think It Feels מתאר ריקנות והתמכרות. The Kids הוא השיר הקשה ביותר: הרשויות לוקחות מקרוליין את הילדים, ובאמצע שומעים ילדים בוכים ומבקשים את אמא. Sad Song, שסוגר את האלבום, הוא פרידה גדולה עם תזמורת ומקהלה, בקולו השקט והמר של ריד.''',
'''המבקרים באמריקה קטלו את האלבום, והוא נכשל שם, אף שבבריטניה הצליח יפה. ריד נפגע, אבל עם השנים Berlin הוערך מחדש כאחד האלבומים האמיצים שלו, ובשנים מאוחרות הוא אף העלה אותו במלואו על הבמה, עם תזמורת. זה אלבום שדומה יותר לסרט או לרומן מאשר לתקליט רוק.''',
'''זה אלבום לשמוע מהתחלה עד הסוף, כמו סרט, ולא ביום עצוב במיוחד. התחילו בשיר הנושא ובקרוליין, ואז בחרו אם אתם מוכנים להמשיך עד The Kids.''',
], [
('Caroline Says II', 'שיר עצוב ורך על אישה פגועה, עם גיטרה אקוסטית.'),
('Sad Song', 'פרידה גדולה עם תזמורת ומקהלה, בקול שקט ומר.'),
('Berlin', 'שיר הנושא: פסנתר של בר ושיר אהבה רך בעיר מחולקת.'),
])

add(279, [
'''ג׳נסיס התחילו כלהקה של תלמידי פנימייה בריטית יוקרתית, ועד 1973 הם כבר היו אחת הלהקות החשובות של הרוק המתקדם: פיטר גבריאל, הזמר, עם תלבושות ומסכות על הבמה, פיל קולינס בתופים, סטיב האקט בגיטרה, טוני בנקס בקלידים ומייק רתרפורד בבס. Selling England by the Pound יצא באוקטובר 1973, והוא עוסק באנגליה: המסורת, הכפר, הנוסטלגיה, והחשש שהיא הופכת למסחרית ונמכרת "לפי הקילו".''',
'''Dancing with the Moonlit Knight נפתח בקולו של גבריאל, לבד, ששר "אתם יכולים לספר לי איפה המדינה שלי?", ומתפתח לפרוג מהיר ומסובך. I Know What I Like הוא שיר משעשע על בחור שמכסח דשא ומרוצה מחייו, והפך ללהיט הראשון של הלהקה. Firth of Fifth כולל פתיחה של פסנתר קלאסי וסולו גיטרה ארוך ויפהפה של האקט, ו־The Cinema Show מתחיל כשיר אהבה אקוסטי ומגיע לסולו סינתסייזר ארוך ועשיר. The Battle of Epping Forest מספר, בקולות רבים, על קרב בין כנופיות מזרח לונדון.''',
'''רבים רואים באלבום את השיא של ג׳נסיס עם גבריאל, שעזב כעבור שנתיים. אחר כך קולינס הפך לזמר, והלהקה עברה לפופ והצליחה מאוד. האלבום משלב את הדמיון הבריטי המשונה של הלהקה עם נגינה מדויקת ויפה, והוא אחד האלבומים המוכרים של הפרוג.''',
'''התחילו ב־I Know What I Like, הכי קצר ונגיש, ואז שמעו את Firth of Fifth והקשיבו לסולו הגיטרה. אם אהבתם את יס (אלבום 249), זה הצד הבריטי, השובב והספרותי יותר, של אותו עולם.''',
], [
('Firth of Fifth', 'פסנתר קלאסי וסולו גיטרה ארוך ויפהפה של סטיב האקט.'),
('I Know What I Like (In Your Wardrobe)', 'שיר משעשע על מכסח דשא מרוצה, הלהיט הראשון של הלהקה.'),
('Dancing with the Moonlit Knight', 'קול בודד ששואל איפה אנגליה, ופרוג מהיר ומסובך.'),
])

add(280, [
'''אחרי What's Going On (אלבום 207), אלבום על מלחמה, עוני וסביבה, מרווין גיי פנה לנושא אחר לגמרי: אהבה ותשוקה. יחד עם הכותב והמפיק אד טאונסנד הוא יצר אלבום רך וחושני, שבו כל השירים עוסקים ברומנטיקה ובגוף, בזמן שנישואיו התפרקו. Let's Get It On יצא באוגוסט 1973.''',
'''שיר הנושא נפתח בגיטרת וואה־וואה מוכרת, ומתפתח לשיר מלא תשוקה ורגש, עם כלי נשיפה, מיתרים והקול של גיי, שעובר מלחישה לצעקה. Distant Lover הוא בלדה עצובה על געגוע לאהובה רחוקה, If I Should Die Tonight הוא שיר אהבה רך ועמוק, ו־Just to Keep You Satisfied, שסוגר את האלבום, הוא שיר פרידה כואב שגיי כתב על אשתו. גיי שר כאן בשכבות: הקול הראשי, קולות ליווי שהוא עצמו מקליט, ולחישות.''',
'''שיר הנושא הגיע למקום הראשון באמריקה, והאלבום היה אחד המצליחים של גיי. הוא נחשב לאחד האלבומים הרומנטיים והחושניים ביותר שנעשו, והשפיע על ז׳אנר שלם של סול רך ורומנטי, ועל זמרי R&B רבים שבאו אחריו.''',
'''שמעו את שיר הנושא ואת Distant Lover, ואז, בנפרד, את Just to Keep You Satisfied. השוו את כל אלה ל־What's Going On (אלבום 207): אותו קול, ונושא אחר לגמרי.''',
], [
('Let\'s Get It On', 'גיטרת וואה־וואה מוכרת ושיר מלא תשוקה.'),
('Distant Lover', 'בלדה עצובה על געגוע לאהובה רחוקה.'),
('Just to Keep You Satisfied', 'שיר פרידה כואב שגיי כתב על נישואיו.'),
])

add(281, [
'''ג׳ון מרטין, זמר וגיטריסט סקוטי, התחיל כזמר פולק צעיר בלונדון, והיה חבר קרוב של ניק דרייק (אלבומים 149, 190 ו־261), שהקליט באותה חברת תקליטים. בתחילת שנות השבעים הוא התחיל לערבב פולק עם ג׳אז ובלוז, ולנגן בגיטרה עם מכשיר "אקופלקס", שמייצר הדים חוזרים. Solid Air, האלבום הרביעי שלו, הוקלט בשמונה ימים בלבד ויצא בתחילת 1973, עם הקונטרבסיסט דני תומפסון מפנטנגל (אלבום 147) וחברים מפיירפורט קונבנשן.''',
'''שיר הנושא, שמרטין הקדיש לניק דרייק, נפתח בקונטרבס עמוק ובסקסופון רך, והקול של מרטין נמרח ומתגלגל כאילו הוא מנגן על כלי נשיפה ולא שר. May You Never הוא שיר אקוסטי חם ופשוט, שבו חבר מאחל לחבר את כל הטוב, ו־Don't Want to Know הוא שיר שקט על רצון לא לדעת על הרע שבעולם. ובאמצע, I'd Rather Be the Devil, בלוז ישן שמרטין מפרק ובונה מחדש עם אקופלקס, תופים ובס, עד שהוא נשמע כמו סערה מהפנטת.''',
'''Solid Air לא היה להיט, אבל הוא נחשב לאחד האלבומים החשובים של הפולק הבריטי ולגשר בינו לבין הג׳אז והמוזיקה הניסיונית. אריק קלפטון הקליט את May You Never, ומוזיקאים רבים הושפעו מהגיטרה ומהקול של מרטין. הוא המשיך להקליט ולהופיע עד מותו ב־2009.''',
'''שמעו את שיר הנושא בשקט, ותחשבו על ניק דרייק. ואז את I'd Rather Be the Devil, והקשיבו איך גיטרה אקוסטית אחת, עם הדים, יכולה להישמע כמו להקה שלמה.''',
], [
('Solid Air', 'שיר הנושא, שהוקדש לניק דרייק: קונטרבס, סקסופון וקול נמרח.'),
('May You Never', 'שיר אקוסטי חם ופשוט, איחול לחבר.'),
('I\'d Rather Be the Devil', 'בלוז ישן שמתפרק לסערה מהפנטת של הדים.'),
])

add(282, [
'''כמה חודשים אחרי אלבום הבכורה (אלבום 263), רוקסי מיוזיק נכנסו לאולפן שוב, והפעם הביטחון שלהם גדל. For Your Pleasure יצא במרץ 1973, עם עטיפה שבה דוגמנית בשמלה שחורה מובילה פנתר ברצועה. זה היה האלבום האחרון עם בריאן אינו, שנפרד מהלהקה אחרי חילוקי דעות עם בריאן פרי, ויצא לקריירת סולו (אלבום 300).''',
'''האלבום אפל, מוזר ואלגנטי יותר מהקודם. Do the Strand פותח בקריאה לרקוד ריקוד חדש ודמיוני, עם פסנתר, סקסופון וגיטרה, כמו מסיבה פרועה. Editions of You הוא רוק מהיר עם סולואים של סינתסייזר וסקסופון. ובמרכז, In Every Dream Home a Heartache: פרי מדבר, בקול שקט ומנוכר, אל בובה מתנפחת שהיא בת הזוג היחידה שלו בבית מפואר וריק, והשיר נגמר, מתחיל שוב, ומתפרץ בסולו גיטרה אדיר של פיל מנזנרה. The Bogus Man ארוך, מאיים וחזרתי, ושיר הנושא נמס ברעשים של אינו.''',
'''For Your Pleasure נחשב בעיני רבים לאלבום הטוב ביותר של רוקסי מיוזיק, והוא השפיע על הפוסט־פאנק ועל הניו וייב של סוף שנות השבעים. הוא משלב גלאם, אוונגרד, רוקנרול וזוהר קולנועי, ומראה איך אלבום רוק יכול להיות גם אירוני וגם מרגש.''',
'''שמעו את In Every Dream Home a Heartache עד הסוף, וחכו לרגע שבו השיר כמעט נגמר ואז חוזר בעוצמה. ואז את Do the Strand, והשוו לרוקסי של אלבום הבכורה (אלבום 263).''',
], [
('In Every Dream Home a Heartache', 'שיר אהבה מנוכר לבובה, שמתפרץ בסולו גיטרה אדיר.'),
('Do the Strand', 'קריאה פרועה לרקוד ריקוד דמיוני, עם פסנתר וסקסופון.'),
('Editions of You', 'רוק מהיר עם סולואים של סינתסייזר וסקסופון.'),
])

add(283, [
'''פאוסט הייתה להקה גרמנית שחבריה חיו יחד בבית ספר כפרי ישן שהפך לאולפן, וניסו ליצור מוזיקה שלא שמעו מעולם: רוק, רעש, הקלטות של שיחות, קולאז׳ים ואלתורים. חברת וירג׳ין הבריטית, שהייתה אז חדשה, החתימה אותם, ואפילו מכרה אחד מאלבומיהם במחיר של סינגל כדי שכולם יוכלו לנסות. ב־1973 הם הגיעו לאנגליה והקליטו את Faust IV באחוזה כפרית שהייתה לאולפן של וירג׳ין.''',
'''האלבום נפתח ב־Krautrock, קטע של כמעט שתים־עשרה דקות שהשם שלו הוא בדיחה על הכינוי שהעיתונות הבריטית נתנה ללהקות הגרמניות: רעש של גיטרות ועוגב שנמשך ונמשך, עד שהתופים נכנסים רק באמצע. אחריו מגיעים דווקא שירים קטנים ויפים: The Sad Skinhead הוא שיר עליז ומשונה בקצב של רגאיי, Jennifer הוא שיר חלומי ומרחף עם בס עמוק וגיטרה שמתפרקת לרעש, ו־It's a Bit of a Pain מתחיל כשיר פולק רך ונקטע שוב ושוב ברעשים צורמים.''',
'''וירג׳ין נפרדה מהלהקה זמן קצר אחרי יציאת האלבום, וכעבור זמן לא רב הלהקה הפסיקה לפעול, וחזרה רק בשנות התשעים. אבל Faust IV נחשב לאחת הקלאסיקות של הקראוטרוק, והשילוב שלו בין רעש, הומור ושירים יפים השפיע על הרוק האלטרנטיבי, על הפוסט־רוק ועל אמני רעש רבים.''',
'''התחילו ב־Jennifer, השיר היפה והנגיש ביותר, ורק אחר כך חזרו ל־Krautrock עם סבלנות. אם אהבתם את Tago Mago של קאן (אלבום 219), זה צד פרוע ומשועשע יותר של אותה סצנה.''',
], [
('Jennifer', 'שיר חלומי ומרחף עם בס עמוק וגיטרה שמתפרקת לרעש.'),
('Krautrock', 'כמעט שתים־עשרה דקות של רעש מהפנט, והתופים נכנסים רק באמצע.'),
('The Sad Skinhead', 'שיר עליז ומשונה בקצב של רגאיי.'),
])

add(284, [
'''הרבי הנקוק היה פסנתרן ג׳אז מבריק, שניגן בחמישייה של מיילס דייוויס ובהקלטות של In a Silent Way (אלבום 145). בתחילת שנות השבעים הוא ניגן ג׳אז ניסיוני וקשה, ואז החליט לשנות כיוון: הוא אהב את הפאנק של סליי סטון (אלבומים 159 ו־206) ושל ג׳יימס בראון, והקים להקה חדשה, "הד האנטרס", כדי לנגן ג׳אז שאפשר לרקוד אליו. Head Hunters יצא באוקטובר 1973.''',
'''באלבום רק ארבעה קטעים, ארוכים וקצביים. Chameleon נפתח בקו בס של סינתסייזר, שהנקוק מנגן בעצמו, ומתפתח לרבע שעה של גרוב, סולואים של סינתסייזר ופסנתר חשמלי ושינויי קצב. Watermelon Man הוא גרסה חדשה ללהיט שהנקוק כתב עשר שנים קודם, ונפתח בנשיפות לתוך בקבוקים, בהשראת מוזיקה מאפריקה. Sly, מחווה לסליי סטון, מהיר ומסובך, ו־Vein Melter איטי, רך וחלומי.''',
'''Head Hunters הפך לאחד מאלבומי הג׳אז הנמכרים ביותר עד אז, והביא את הג׳אז לקהל צעיר של פאנק ורוק. חובבי ג׳אז שמרנים כעסו, אבל האלבום השפיע על הפאנק, על הפיוז׳ן ועל ההיפ הופ, שדגם אותו רבות. הנקוק המשיך לחצות גבולות, ובשנות השמונים הוציא גם להיט אלקטרוני.''',
'''שמעו את Chameleon, והקשיבו לקו הבס בהתחלה: הוא חוזר כל הזמן, וכל השאר נבנה עליו. אחר כך השוו ל־In a Silent Way של מיילס דייוויס (אלבום 145), שבו הנקוק ניגן בפסנתר חשמלי: ג׳אז חשמלי שקט, לפני שהפך לפאנק.''',
], [
('Chameleon', 'רבע שעה של גרוב, עם קו בס מפורסם של סינתסייזר.'),
('Watermelon Man', 'להיט ישן בגרסה חדשה, שנפתחת בנשיפות לבקבוקים.'),
('Sly', 'מחווה מהירה ומסובכת לסליי סטון.'),
])

add(285, [
'''מוט דה הופל היו להקת רוק בריטית שעבדה קשה והופיעה הרבה, אבל כמעט לא מכרה, וב־1972 הם עמדו להתפרק. דייוויד בואי, מעריץ שלהם, נתן להם שיר שכתב, All the Young Dudes, הפיק להם אלבום, והשיר הפך ללהיט גדול. עכשיו הם היו צריכים להוכיח שהם מסוגלים לבד. Mott, שהפיקו בעצמם, יצא ביולי 1973, והזמר והכותב איאן האנטר, עם משקפי שמש ושיער מתולתל, הוביל אותו.''',
'''זה רוק גלאם עם לב של רוקנרול ישן ועם מילים אישיות וכנות. All the Way from Memphis פותח בפסנתר דוהר וסקסופון, ומספר בהומור על חיי להקה בדרכים, ועל גיטרה שנשלחה בטעות לעיר אחרת. Honaloochie Boogie הוא רוק שמח וקליט, ו־Hymn for the Dudes הוא בלדה גדולה ומלאת רגש, כמו המשך לשיר של בואי. ו־Ballad of Mott the Hoople הוא שיר עצוב ויפה על הלהקה עצמה, על הרגע שבו כמעט התפרקה ועל החלומות שנשברו.''',
'''Mott הגיע לעשירייה הראשונה בבריטניה, ורבים רואים בו את האלבום הטוב של הלהקה. אבל היא לא שרדה הרבה: הגיטריסט מיק ראלפס עזב והקים את להקת בד קומפני, והאנטר עזב כעבור שנה לקריירת סולו. השירים של האנטר, על החיים של להקת רוק מבפנים, השפיעו על הפאנק ועל להקות רבות, מהקלאש ועד מוריסי.''',
'''שמעו את All the Way from Memphis ואת Ballad of Mott the Hoople: שני שירים על אותה להקה, אחד מצחיק ואחד עצוב. אם אהבתם את בואי של אותה תקופה (אלבומים 266 ו־272), תרגישו בבית.''',
], [
('All the Way from Memphis', 'פסנתר דוהר, סקסופון והומור על חיי להקה בדרכים.'),
('Ballad of Mott the Hoople', 'שיר עצוב ויפה על הלהקה עצמה ועל החלומות שנשברו.'),
('Honaloochie Boogie', 'רוק שמח וקליט עם פסנתר וכפיים.'),
])

add(286, [
'''מייק אולדפילד היה נער ביישן בן תשע־עשרה, שניגן בגיטרה בלהקות אחרות וחלם על יצירה אינסטרומנטלית ארוכה. אף חברת תקליטים לא התעניינה, עד שריצ׳רד ברנסון, יזם צעיר שפתח חנות תקליטים ואולפן באחוזה כפרית, החליט להקים חברה חדשה, וירג׳ין, ולהוציא את היצירה כתקליט הראשון שלה. אולדפילד ניגן כמעט על כל הכלים בעצמו, עשרות כלים, והקליט אותם שכבה על שכבה. Tubular Bells יצא במאי 1973.''',
'''היצירה בנויה משני חלקים, אחד לכל צד של התקליט. היא נפתחת בנושא מפורסם ומסתורי של פסנתר, בקצב משונה, ומשם עוברת בין גיטרות אקוסטיות וחשמליות, עוגב, בס, מנדולינה, פסנתר ותופים, בין רגעים שקטים ופסטורליים לרגעים סוערים. בסוף החלק הראשון, קול מכריז על כל כלי שנכנס, אחד אחרי השני, עד שבשיא מגיעים ה"פעמונים הצינוריים" של השם. החלק השני כולל גם קטע פרוע שבו אולדפילד נוהם כמו איש מערות, וסיום מפתיע ושמח.''',
'''הנושא הפותח הופיע בסרט האימה "מגרש השדים" כעבור כמה חודשים, והאלבום הפך להצלחה עצומה, נמכר במיליונים ונשאר במצעדים שנים. וירג׳ין הפכה לאימפריה, ואולדפילד לאחד המוזיקאים המצליחים בבריטניה. Tubular Bells הראה שיצירה אינסטרומנטלית ארוכה, כמעט קלאסית, יכולה לכבוש קהל של רוק.''',
'''שמעו את החלק הראשון מההתחלה עד הסוף, והקשיבו להכרזה על הכלים בסוף: מנסים לזהות כל אחד מהם כשהוא נכנס. אם אהבתם את Close to the Edge של יס (אלבום 249), זה מסע ארוך מסוג אחר.''',
], [
('Tubular Bells, Part One', 'הנושא המפורסם של הפסנתר, מסע של כלים והכרזה על כל אחד מהם.'),
('Tubular Bells, Part Two', 'רגעים פסטורליים, נהמות של איש מערות וסיום מפתיע.'),
])

add(287, [
'''אחרי ההצלחה של Something/Anything? (אלבום 253), טוד רנדגרן יכול היה להמשיך לכתוב להיטי פופ בקלות. במקום זה, הוא בנה לעצמו אולפן בניו יורק, התנסה בחומרים משני תודעה, והקליט אלבום שבו השירים זורמים זה לתוך זה בלי הפסקה, כמו זרם תודעה. A Wizard, a True Star יצא במרץ 1973, ובו תשעה־עשר שירים דחוסים לתקליט אחד, קרוב לשעה של מוזיקה.''',
'''הצד הראשון הוא רצף פרוע של קטעים קצרים: שירי פופ, רעשים אלקטרוניים, מחווה למחזמר "פיטר פן", רוק כבד, צחוקים, שינויי קצב ואפקטים. International Feel פותח בצלילים חלליים ובפופ עליז, ו־Zen Archer הוא שיר רך ויפה. הצד השני מתקרב יותר לשירים רגילים: Sometimes I Don't Know What to Feel ו־Does Anybody Love You? הם שירי סול רכים, יש מחרוזת אהבה לארבעה שירי סול מוכרים משנות השישים, ו־Just One Victory סוגר את האלבום בהמנון אופטימי, שקורא לא לוותר.''',
'''הקהל שאהב את הלהיטים של רנדגרן נבהל, והאלבום נמכר הרבה פחות. אבל עם השנים הוא הפך לאלבום פולחן, ומוזיקאים רבים, שניסו לערבב פופ וניסויים באולפן, ציינו אותו כהשראה.''',
'''שמעו את הצד הראשון בבת אחת, בלי לעצור, כמו חלום משונה. ואז דלגו ל־Just One Victory. השוו את כל אלה לפופ המסודר של Something/Anything? (אלבום 253).''',
], [
('Just One Victory', 'המנון אופטימי שקורא לא לוותר, וסוגר את האלבום.'),
('International Feel', 'הפותח: צלילים חלליים ופופ עליז.'),
('Sometimes I Don\'t Know What to Feel', 'שיר סול רך ויפה, עם קולות ליווי חמים.'),
])

add(288, [
'''אלטון ג׳ון והתמלילן ברני טאופין (אלבום 220) היו ב־1973 מהצמדים המצליחים בעולם, וכתבו שירים במהירות מדהימה: טאופין כתב מילים, ואלטון הלחין אותן לפעמים תוך דקות. הם תכננו להקליט בג׳מייקה, אבל התנאים שם לא התאימו, והם עברו לטירה צרפתית שהפכה לאולפן. שם, בכמה שבועות, נולדו מספיק שירים לאלבום כפול. Goodbye Yellow Brick Road יצא באוקטובר 1973.''',
'''האלבום נפתח ב־Funeral for a Friend/Love Lies Bleeding, יצירה של אחת־עשרה דקות שמתחילה בסינתסייזר קודר ורוח, ומתפרצת לרוק גדול. Candle in the Wind הוא שיר רך על מרלין מונרו, על תהילה ועל בדידות. Bennie and the Jets הוא שיר משונה ומשעשע על להקה דמיונית, עם מחיאות כפיים של קהל ופסנתר קופצני, ושיר הנושא הוא בלדה יפה על כוכב שרוצה לחזור לחיים פשוטים. יש גם רוק מהיר כמו Saturday Night's Alright for Fighting, ושירים של קאנטרי, רגאיי ופופ.''',
'''האלבום הגיע למקום הראשון באמריקה ונשאר שם שבועות רבים, והפך לאחד האלבומים הנמכרים של שנות השבעים. Candle in the Wind חזר ב־1997, במילים חדשות, לזכרה של הנסיכה דיאנה, והפך לאחד הסינגלים הנמכרים בהיסטוריה. זה אלטון בשיא: כוכב גדול, עם שירים מכל הסוגים.''',
'''זה אלבום ארוך, אז התחילו בשיר הנושא, Candle in the Wind ו־Bennie and the Jets. ואם יש לכם אחת־עשרה דקות, שמעו את הפתיחה, באוזניות.''',
], [
('Goodbye Yellow Brick Road', 'בלדה יפה על כוכב שרוצה לחזור לחיים פשוטים.'),
('Candle in the Wind', 'שיר רך על מרלין מונרו, על תהילה ועל בדידות.'),
('Bennie and the Jets', 'פסנתר קופצני ומחיאות כפיים, על להקה דמיונית.'),
])

add(289, [
'''סטילי דן, הלהקה של וולטר בקר ודונלד פייגן (אלבום 244), הצליחה עם אלבום הבכורה, ויצאה לסיבוב הופעות ארוך. הרבה מהשירים של האלבום השני נכתבו בדרכים, והפעם הם נשמעים כמו להקה שמנגנת יחד, עם שני גיטריסטים שמתחרים בסולואים. Countdown to Ecstasy יצא ביולי 1973.''',
'''הצליל חד יותר ורוקי יותר מהאלבום הקודם, עם השפעות ג׳אז ברורות: אקורדים מסובכים, סולואים ארוכים ומילים ציניות ומלאות רמזים. Bodhisattva פותח ברוק שמח ומהיר, שצוחק על מערביים שמחפשים הארה במזרח. My Old School הוא רוק קצבי עם כלי נשיפה, על קולג׳ שהכותבים עזבו בלי געגועים, ו־Show Biz Kids הוא ביקורת חריפה על עשירי לוס אנג׳לס, עם גיטרת סלייד וקולות ליווי שחוזרים על משפט אחד. Your Gold Teeth ג׳אזי ומתפתל, ו־King of the World מסיים בסיפור מדע בדיוני על אדם אחרון אחרי מלחמה גרעינית.''',
'''האלבום נמכר פחות מהקודם, אבל רבים מהמעריצים רואים בו את אחד האלבומים הטובים של הלהקה, וכמעט היחיד שבו היא נשמעת כמו להקה אמיתית. אחריו בקר ופייגן הפסיקו להופיע, והקליטו את האלבומים הבאים עם נגני אולפן מהטובים בעולם.''',
'''שמעו את Bodhisattva ואת My Old School בקול רם. אחר כך השוו ל־Can't Buy a Thrill (אלבום 244), ושימו לב איך הלהקה נשמעת כאן חיה ורוקית יותר.''',
], [
('My Old School', 'רוק קצבי עם כלי נשיפה, על קולג׳ שעזבו בלי געגועים.'),
('Bodhisattva', 'רוק מהיר שצוחק על מחפשי הארה במזרח.'),
('Show Biz Kids', 'ביקורת חריפה על עשירי לוס אנג׳לס, עם גיטרת סלייד.'),
])

add(290, [
'''ויילון ג׳נינגס התחיל כנגן בס בלהקה של באדי הולי (אלבום 8), ובמקרה ויתר על מקומו במטוס שהתרסק ב־1959 והרג את הולי. בשנות השישים הוא הפך לזמר קאנטרי בנאשוויל, אבל סבל מהשיטה שם: מפיקים שבחרו לו שירים ונגני אולפן שהחליפו את הלהקה שלו. בתחילת שנות השבעים הוא דרש שליטה מלאה על ההקלטות. ב־1972 הוא שמע בפסטיבל בטקסס את בילי ג׳ו שייבר, כותב שירים צעיר ומחוספס, והבטיח לו להקליט אלבום שלם של שיריו. Honky Tonk Heroes יצא ביוני 1973.''',
'''זה קאנטרי פשוט, יבש ומחוספס: בלי מיתרים ובלי מקהלות, רק הלהקה של ג׳נינגס, בס כבד, תופים, גיטרות, והקול העמוק והמחוספס שלו. השירים של שייבר מספרים על שתיינים, נוודים, אנשים עניים ואוהבי חופש: שיר הנושא מדבר על גיבורי הבר המקומי, Old Five and Dimers Like Me הוא שיר נוגה על אדם שלא הצליח בחיים ולא מתבייש, ו־Willy the Wandering Gypsy and Me הוא שיר על נוודות ועל חופש. Ain't No God in Mexico הוא סיפור משעשע ומר על חוויה במקסיקו.''',
'''Honky Tonk Heroes נחשב לאלבום המכונן של תנועת ה"אאוטלו קאנטרי": זמרים כמו ג׳נינגס ווילי נלסון, שהתמרדו נגד נאשוויל המלוטשת וחזרו לקאנטרי מחוספס ואישי. האלבום גם הפך את בילי ג׳ו שייבר לכותב נערץ, והשפיע על דורות של זמרי קאנטרי ואמריקנה.''',
'''שמעו את שיר הנושא ואת Old Five and Dimers Like Me, והשוו לקאנטרי של רוי פרייס (אלבום 34) או של מרל הגרד (אלבום 99): אותה מסורת, ויותר רוק, יותר אבק ויותר חופש.''',
], [
('Honky Tonk Heroes', 'שיר הנושא על גיבורי הבר המקומי, עם בס כבד וקול מחוספס.'),
('Old Five and Dimers Like Me', 'שיר נוגה על אדם שלא הצליח בחיים ולא מתבייש בזה.'),
('Willy the Wandering Gypsy and Me', 'שיר על נוודות, דרכים וחופש.'),
])

add(291, [
'''פינק פלויד חיפשו את דרכם במשך כמה שנים אחרי שסיד בארט עזב (אלבומים 89 ו־203). בשנים 1972–1973 הם בנו, בהופעות ובאולפני אבי רואד, יצירה אחת שלמה על הלחצים שמשגעים אנשים: הזמן שבורח, הכסף, המלחמה, הפחד מהמוות והשיגעון עצמו, שמזכיר את מה שקרה לבארט. רוג׳ר ווטרס כתב את כל המילים, והמהנדס הצעיר אלן פרסונס עזר לבנות את הצליל. The Dark Side of the Moon יצא במרץ 1973, עם עטיפה שחורה ובה מנסרה שמפרקת קרן אור לצבעים.''',
'''האלבום זורם מהתחלה ועד הסוף בלי הפסקות, כמו מסע אחד. דופק לב, שעונים מתקתקים, קופות רושמות וקולות של אנשים שנשאלו שאלות על מוות, אלימות ושיגעון נשזרים בתוך השירים. Time נפתח בעשרות שעונים מצלצלים ומזהיר שהחיים עוברים מהר, The Great Gig in the Sky הוא קטע שבו הזמרת קלייר טורי מאלתרת בלי מילים, בצעקה מרגשת של כאב ושחרור, ו־Money בנוי על קו בס בקצב משונה ועל צלילי מטבעות. Us and Them איטי ורחב, עם סקסופון, ו־Brain Damage ו־Eclipse סוגרים בשיא גדול.''',
'''זה אחד האלבומים הנמכרים בהיסטוריה, והוא נשאר במצעד האלבומים האמריקאי יותר מ־900 שבועות. הצליל שלו, הנקי והמדויק, הפך לאמת מידה לאיכות הקלטה, ומערכות סטריאו נבדקו עליו במשך עשורים. המנסרה על העטיפה היא אחת התמונות המוכרות בעולם.''',
'''זה אלבום שחייבים לשמוע מהתחלה עד הסוף, באוזניות, בלי הפרעות. מהדופק הראשון עד הדופק האחרון יש פחות מ־45 דקות.''',
], [
('Time', 'עשרות שעונים מצלצלים ושיר על החיים שעוברים מהר מדי.'),
('The Great Gig in the Sky', 'קלייר טורי מאלתרת בלי מילים: צעקה של כאב ושחרור.'),
('Money', 'קו בס בקצב משונה, מטבעות וקופות רושמות.'),
])

add(292, [
'''שנה אחרי Talking Book (אלבום 255), סטיבי וונדר הוציא את Innervisions, ושוב ניגן כמעט הכול בעצמו: קלידים, סינתסייזרים, תופים, בס ומפוחית. הפעם השירים עוסקים פחות באהבה ויותר בחברה: עוני, גזענות, סמים, פוליטיקה ואמונה. האלבום יצא באוגוסט 1973, וכמה ימים אחר כך וונדר נפצע קשה בתאונת דרכים ושכב ימים אחדים בתרדמת. הוא התאושש, וחזר למוזיקה כמעט במלוא הכוח.''',
'''Living for the City מספר על בחור צעיר ממיסיסיפי שמגיע לניו יורק בחיפוש אחרי חיים טובים יותר, ובאמצע השיר יש סצנה מוקלטת, כמו מסרט, שבה הוא נעצר ונשלח לכלא. Higher Ground הוא פאנק כבד עם קלבינט, על הזדמנות שנייה בחיים, ו־Don't You Worry 'bout a Thing הוא שיר שמח עם קצב לטיני ופסנתר. Too High מזהיר מסמים, Golden Lady ו־All in Love Is Fair הם בלדות יפות, ו־He's Misstra Know-It-All לועג, כנראה, לנשיא ניקסון.''',
'''Innervisions זכה בפרס הגראמי לאלבום השנה, ונחשב בעיני רבים לאלבום הטוב ביותר של וונדר. הוא הראה שסול יכול להיות גם פוליטי, גם אישי וגם רוקד, והשפיע על אמני סול, היפ הופ ופופ רבים. וונדר זכה בשנים שאחריו בעוד שני פרסי אלבום השנה.''',
'''שמעו את Living for the City עד הסוף, כולל הסצנה המוקלטת, והקשיבו איך הקול של וונדר נעשה צרוד וזועם לקראת הסוף. אחר כך את Higher Ground, כדי לשמוע אותו רוקד.''',
], [
('Living for the City', 'סיפור על בחור שמגיע לניו יורק, עם סצנה מוקלטת וקול זועם.'),
('Higher Ground', 'פאנק כבד עם קלבינט, על הזדמנות שנייה.'),
('Don\'t You Worry \'bout a Thing', 'שיר שמח עם קצב לטיני ופסנתר.'),
])

add(293, [
'''זי זי טופ הם שלישייה מטקסס: הגיטריסט והזמר בילי גיבונס, הבסיסט דאסטי היל והמתופף פרנק בירד (שמו פירושו "זקן", אבל דווקא לו לא היה זקן). הם ניגנו בלוז רוק כבד בברים ובמועדונים של הדרום, ו־Tres Hombres, "שלושה גברים" בספרדית, האלבום השלישי שלהם, יצא ביולי 1973. בתוך העטיפה המקורית הייתה תמונה של צלחת אוכל מקסיקני.''',
'''זה בלוז רוק פשוט ושמן: גיטרה מחוספסת עם צליל עבה, בס ותופים שמתגלגלים בקצב של בוגי, ושירים על בירה, מכוניות, בחורות וחיי טקסס. La Grange, השיר המפורסם, נבנה על ריף בוגי ישן בהשראת ג׳ון לי הוקר, ומספר על "בית" מפורסם בעיירה קטנה בטקסס, בית שכולם ידעו מה קורה בו. Waitin' for the Bus ו־Jesus Just Left Chicago מתחברים זה לזה ברצף, מבלוז מהיר לבלוז איטי ועמוק, ו־Beer Drinkers & Hell Raisers הוא רוק פרוע של בר.''',
'''האלבום הפך את זי זי טופ לכוכבים, ו־La Grange נשמע עד היום בכל תחנת רדיו של רוק קלאסי. בשנות השמונים הלהקה הפכה לכוכבת של ערוצי הקליפים, עם זקנים ארוכים ומכוניות, אבל כאן הם עוד להקת בלוז של הדרום.''',
'''שמעו את La Grange בקול רם, וחכו לסולו הגיטרה. ואז את Waitin' for the Bus ו־Jesus Just Left Chicago יחד, כמו בתקליט. אם אהבתם את Led Zeppelin (אלבום 154), תשמעו כאן בלוז כבד, פשוט וטקסני יותר.''',
], [
('La Grange', 'ריף בוגי מפורסם וסיפור על "בית" בעיירה קטנה בטקסס.'),
('Waitin\' for the Bus', 'בלוז מהיר עם מפוחית, שמתחבר לשיר הבא.'),
('Jesus Just Left Chicago', 'בלוז איטי ועמוק, עם גיטרה מלאת צליל.'),
])

add(294, [
'''בשנים הראשונות אחרי הביטלס, פול מקרטני (אלבום 201) ספג ביקורות קשות, והלהקה החדשה שלו, ווינגס, נראתה לרבים חלשה. ב־1973 הוא החליט להקליט בלגוס שבניגריה, אבל ערב הנסיעה שניים מחברי הלהקה עזבו, ורק פול, אשתו לינדה והגיטריסט דני ליין נסעו. בלגוס הם נשדדו באיומי סכין ואיבדו הקלטות של שירים, והאולפן היה פשוט ומאולתר. ובכל זאת, Band on the Run, שיצא בדצמבר 1973, הפך להצלחה הגדולה של מקרטני אחרי הביטלס.''',
'''שיר הנושא בנוי משלושה חלקים שונים לגמרי: פתיחה איטית ועצובה על אסירים בתא, קטע רוקי קצר, ואז הבריחה: גיטרה אקוסטית ושיר על להקה שנמלטת מהסוהרים. Jet הוא רוק שמח וסוער, עם צעקות וכלי נשיפה, Bluebird הוא שיר רך ואקוסטי על ציפור שעפה לחופש, ו־Let Me Roll It הוא רוק איטי וכבד שמזכיר את ג׳ון לנון. ב־Picasso's Last Words מקרטני לקח את המילים האחרונות של פיקאסו והפך אותן לשיר.''',
'''האלבום הגיע למקום הראשון באמריקה ובבריטניה, והמבקרים סוף סוף הודו שמקרטני עדיין מסוגל ליצור אלבום שלם וגדול. על העטיפה מופיעים חברי הלהקה וכמה ידוענים בריטים, כולם כמו אסירים שנתפסו באור זרקור. מוזיקאי האפרוביט פלה קוטי (אלבום 232) חשד בזמנו שמקרטני בא לגנוב את המוזיקה של אפריקה, אבל כשהקשיב לשירים הבין שאין לו מה לדאוג: האלבום לא נשמע אפריקאי במיוחד.''',
'''שמעו את שיר הנושא, וחכו לרגע שבו הגיטרה האקוסטית נכנסת והבריחה מתחילה. ואז את Jet, בקול רם. אם אהבתם את McCartney (אלבום 201), תשמעו איך הסקיצות הביתיות הפכו לאלבום גדול.''',
], [
('Band on the Run', 'שלושה חלקים: אסירים בתא, רוק קצר, ואז הבריחה הגדולה.'),
('Jet', 'רוק שמח וסוער עם צעקות וכלי נשיפה.'),
('Bluebird', 'שיר רך ואקוסטי על ציפור שעפה לחופש.'),
])

add(295, [
'''אלכס הארווי מגלזגו שר רוקנרול כבר מסוף שנות החמישים, בלי הצלחה גדולה, והיה כמעט בן ארבעים כשפגש להקה צעירה מסקוטלנד והקים איתה את "להקת אלכס הארווי המרעישה". הם הביאו לבמה תיאטרון של ממש: הארווי כמו מספר סיפורים משוגע, והגיטריסט זאל קלמינסון באיפור של ליצן. Next, האלבום השני שלהם, יצא בנובמבר 1973.''',
'''זה רוק כבד ותיאטרלי, מלא הומור שחור ודמויות מוזרות. The Faith Healer נפתח בפעימה אלקטרונית איטית ומאיימת, שנבנית לאט לרוק מהפנט, כשהארווי שר בתור מרפא דתי שמבטיח ישועה. Giddy Up a Ding Dong הוא רוקנרול שמח משנות החמישים, ו־Vambo Marble Eye מספר על גיבור רחוב דמיוני. ושיר הנושא הוא גרסה לשיר של ז׳אק ברל (אלבום 43), עם אקורדיון ומקצב טנגו, על חייל צעיר שעומד בתור בבית בושת צבאי, והארווי שר אותו בזעם ובייאוש של שחקן על במה.''',
'''הלהקה הפכה בשנים שאחר כך לאחת הלהקות המבוקשות בבריטניה, בזכות ההופעות הפרועות שלה, והשפיעה על הפאנק שבא אחריה. הארווי מת ב־1982, בגיל ארבעים ושש, אבל נשאר דמות אהובה, במיוחד בסקוטלנד.''',
'''שמעו את The Faith Healer עד הסוף, ותנו לו לבנות את המתח. ואז את שיר הנושא, והשוו לז׳אק ברל עצמו באולימפיה (אלבום 43).''',
], [
('The Faith Healer', 'פעימה אלקטרונית מאיימת שנבנית לרוק מהפנט.'),
('Next', 'שיר של ז׳אק ברל בגרסת טנגו תיאטרלית וזועמת.'),
('Vambo Marble Eye', 'רוק כבד על גיבור רחוב דמיוני.'),
])

add(296, [
'''אחרי School's Out (אלבום 264), להקת אליס קופר הייתה בשיא: ההופעות שלה היו מופעי אימה ענקיים, עם גיליוטינה, נחשים ובובות, וההורים באמריקה שנאו אותה, מה שרק הגדיל את ההצלחה. Billion Dollar Babies, שהפיק שוב בוב אזרין, יצא בתחילת 1973, והגיע למקום הראשון באמריקה ובבריטניה. העטיפה המקורית נראתה כמו ארנק ענק, ובתוכה שטר של מיליארד דולר.''',
'''זה רוק כבד, מלוטש וחכם, מלא הומור מרושע. Hello Hooray פותח בהזמנה חגיגית לבמה, כמו מחזמר. Elected הוא פרודיה על קמפיין בחירות, עם כלי נשיפה ומקהלות, ושיר הנושא, דואט עם זמר הפולק דונובן (אלבום 98), מתאר תינוקות עשויים כסף. No More Mr. Nice Guy הוא שיר רוק קליט על מי שנמאס לו להיות נחמד, Generation Landslide מספר על דור שמסתבך, ו־I Love the Dead סוגר באימה מכוונת ומוגזמת, שנועדה בעיקר לזעזע.''',
'''האלבום היה ההצלחה הגדולה ביותר של להקת אליס קופר, וסיבוב ההופעות שבא אחריו היה מהגדולים של התקופה. אבל הלחץ פירק את הלהקה, ואליס המשיך לבד. השילוב בין רוק כבד, הומור ומופעי אימה השפיע על דורות של להקות מטאל ושוק רוק.''',
'''שמעו את Elected ואת No More Mr. Nice Guy, שני שירים קליטים וחכמים. ואז השוו את השירים לאלה של School's Out (אלבום 264).''',
], [
('No More Mr. Nice Guy', 'שיר רוק קליט על מי שנמאס לו להיות נחמד.'),
('Elected', 'פרודיה על קמפיין בחירות, עם כלי נשיפה ומקהלות.'),
('Billion Dollar Babies', 'שיר הנושא, דואט עם דונובן על תינוקות של כסף.'),
])

add(297, [
'''אחרי שני אלבומים שלא נמכרו (אלבומים 171 ו־199), הסטוג׳ס התפרקו, ואיגי פופ נראה גמור. אבל דייוויד בואי, מעריץ ותיק, עזר לו לחתום עם המנהל שלו ועם חברת תקליטים גדולה, ואיגי נסע ללונדון עם הגיטריסט החדש ג׳יימס וויליאמסון. אחר כך הצטרפו אליהם גם האחים אשטון מהלהקה המקורית, ורון אשטון, שהיה הגיטריסט, עבר לנגן בבס. Raw Power יצא בתחילת 1973, תחת השם איגי והסטוג׳ס.''',
'''זה רוק מהיר, זועם ומסוכן: הגיטרה של וויליאמסון חדה כמו תער, והקול של איגי צועק, מתגרה ומתנשף. Search and Destroy פותח בריף אדיר ובשורה המפורסמת על "חתול משוחרר מלב של נפאלם", כמו חייל משוגע. Gimme Danger איטי, אקוסטי ומאיים, Penetration מלא מתח, ו־Death Trip סוגר בכאוס מוחלט. בואי ערבב את האלבום במהירות, והתוצאה נשמעת דקה ומרוסקת, ובשנות התשעים איגי ערבב אותו מחדש ברעש מלא.''',
'''האלבום כמעט לא נמכר, והלהקה התפרקה שוב שנה אחר כך. אבל רוקרים צעירים שמעו אותו, ובמיוחד את Search and Destroy, והוא הפך לאחד מאבות הפאנק: להקות כמו הסקס פיסטולס, הרמונס והדמנד הושפעו ממנו ישירות. גם זמרי גראנג׳ ורוק אלטרנטיבי מנו אותו בין האלבומים האהובים עליהם.''',
'''שמעו את Search and Destroy בקול רם מאוד, ואז את Gimme Danger. השוו לאלבום הבכורה של הסטוג׳ס (אלבום 171): הלהקה חדה ומהירה יותר, ואיגי מאיים עוד יותר.''',
], [
('Search and Destroy', 'ריף אדיר וזעם של חייל משוגע: מאבות הפאנק.'),
('Gimme Danger', 'שיר איטי, אקוסטי ומאיים.'),
('Raw Power', 'שיר הנושא: רוקנרול מהיר עם פסנתר דופק.'),
])

add(298, [
'''האחים אייזלי, רונלד, רודולף ואו׳קלי, שרו מסוף שנות החמישים, והלהיטים שלהם כמו Shout ו־Twist and Shout היו מהשירים שהביטלס אהבו. בתחילת שנות השישים ג׳ימי הנדריקס הצעיר ניגן בלהקה שלהם. ב־1973 הם צירפו את האחים הצעירים, ארני, גיטריסט בהשראת הנדריקס, ומרווין, בסיסט, ואת גיסם כריס ג׳ספר בקלידים. כך נולד השם 3+3: שלושה זמרים ושלושה נגנים, להקת סול, פאנק ורוק שלמה.''',
'''That Lady, גרסה חדשה לשיר ישן שלהם, נפתח בגרוב רך ושקט, עם כלי הקשה ושירה עדינה של רונלד, ובאמצע ארני מתפרץ בסולו גיטרה פזיז ומלא הדים שנשמע כמו הנדריקס. גם Summer Breeze, שיר של הצמד סילס וקרופטס, הופך אצלם לבלדת סול רכה עם סולו גיטרה. יש כאן עוד גרסאות לשירי רוק ופופ, בהם Don't Let Me Be Lonely Tonight של ג׳יימס טיילור (אלבום 200) ו־Listen to the Music של הדובי ברדרס, ושירים שלהם, מלאי גרוב וקולות.''',
'''3+3 היה האלבום הראשון של האייזלי ברדרס שנמכר במיליון עותקים, ופתח את העשור המצליח ביותר שלהם. That Lady הגיע לעשירייה הראשונה באמריקה. השילוב של סול, פאנק ורוק, וקול רך מול גיטרה צורחת, השפיע על מוזיקאים רבים, והשירים שלהם נדגמו אחר כך בהיפ הופ.''',
'''שמעו את That Lady וחכו לסולו של ארני. ואז השוו את Don't Let Me Be Lonely Tonight לגרסה של ג׳יימס טיילור, ותשמעו איך שיר פולק שקט הופך לסול.''',
], [
('That Lady', 'גרוב רך ושקט, וסולו גיטרה פזיז שנשמע כמו הנדריקס.'),
('Summer Breeze', 'שיר פופ רך שהופך לבלדת סול עם סולו גיטרה.'),
('Don\'t Let Me Be Lonely Tonight', 'שיר של ג׳יימס טיילור בגרסת סול חמה.'),
])

add(299, [
'''הניו יורק דולס היו חמישה בחורים ממנהטן שלבשו שמלות, נעלי עקב ואיפור, וניגנו רוקנרול פשוט, רועש ולא מדויק, כמו הרולינג סטונס של הימים הראשונים, רק פרועים יותר. הם הופיעו במועדונים קטנים בניו יורק, והמתופף הראשון שלהם מת ב־1972 בלונדון, בזמן סיבוב הופעות. אלבום הבכורה, בהפקת טוד רנדגרן (אלבומים 253 ו־287), יצא ביולי 1973, ועל העטיפה הם יושבים על ספה בבגדי נשים ובאיפור כבד.''',
'''הגיטרות צורמות, התופים דופקים, והקול של דייוויד ג׳והנסן צועק, מתגרה ומשתעשע. Personality Crisis פותח בפסנתר, בצעקה ובאנרגיה של מסיבה שיצאה משליטה, על משבר זהות בעיר הגדולה. Trash הוא רוקנרול עליז וקליט, Jet Boy דוהר ומתפרע, ו־Lonely Planet Boy הוא שיר רך ובודד עם סקסופון. Frankenstein ארוך וכבד, ו־Looking for a Kiss נפתח בציטוט חצוף משיר של להקת בנות משנות השישים.''',
'''האלבום כמעט לא נמכר, והמבקרים התחלקו בין מי שאהב ומי ששנא. אבל הדולס השפיעו מאוד: מלקולם מקלארן, שניהל אותם לזמן קצר, ייסד אחר כך את הסקס פיסטולס, ומוזיקאים רבים בלונדון ובניו יורק ראו בהם את מבשרי הפאנק. הגלאם והפאנק נפגשים כאן, באלבום רועש, פרוע וכיפי.''',
'''שמעו את Personality Crisis ואת Trash בקול רם, ואל תחפשו דיוק. אחר כך השוו לסטוג׳ס של Raw Power (אלבום 297): שתי להקות שהכינו את הקרקע לפאנק.''',
], [
('Personality Crisis', 'פסנתר, צעקה ומסיבה שיצאה משליטה.'),
('Trash', 'רוקנרול עליז וקליט עם גיטרות צורמות.'),
('Jet Boy', 'רוק דוהר ומתפרע שסוגר את האלבום.'),
])

add(300, [
'''בריאן אינו היה חבר ברוקסי מיוזיק (אלבומים 263 ו־282), שם ניגן בסינתסייזר ושינה את הצלילים של האחרים, ועזב אחרי חילוקי דעות עם בריאן פרי. הוא לא ראה את עצמו כמוזיקאי במובן הרגיל, אלא כמי שמכוון תהליך: באלבום הסולו הראשון שלו הוא הזמין נגנים שונים, מחברי רוקסי ועד רוברט פריפ מקינג קרימזון (אלבומים 167 ו־273), ולפעמים הדריך אותם בתנועות ידיים ובריקוד במקום בתווים. Here Come the Warm Jets הוקלט בסתיו 1973 ויצא בתחילת 1974.''',
'''התוצאה היא פופ מוזר, מבריק ומשעשע: שכבות של גיטרות מעוותות, סינתסייזרים, קולות מעובדים ומלודיות קליטות. Needles in the Camel's Eye פותח בקיר של גיטרות מזמזמות ובמלודיה שמחה, Baby's on Fire כולל סולו גיטרה ארוך ופרוע של פריפ, ו־Cindy Tells Me הוא שיר פופ רך ונוסטלגי. On Some Faraway Beach נבנה לאט, כמו תפילה, עם פסנתר וקולות, ושיר הנושא סוגר בגל של צליל חם ומטושטש. אינו כתב את המילים לפי הצליל שלהן יותר מלפי המשמעות.''',
'''Here Come the Warm Jets השפיע רבות על הפאנק, על הניו וייב ועל הרוק האלטרנטיבי. אינו המשיך להמציא את מוזיקת האמביינט השקטה, והפך לאחד המפיקים החשובים בעולם, עם דייוויד בואי, טוקינג הדס, U2 ורבים אחרים.''',
'''שמעו את Needles in the Camel's Eye ואת Baby's on Fire בקול רם, ואז את On Some Faraway Beach בשקט. השוו לרוקסי מיוזיק (אלבום 263), ושמעו כמה מהצליל שלה היה של אינו.''',
], [
('Needles in the Camel\'s Eye', 'קיר של גיטרות מזמזמות ומלודיה שמחה.'),
('Baby\'s on Fire', 'שיר מוזר עם סולו גיטרה ארוך ופרוע של רוברט פריפ.'),
('On Some Faraway Beach', 'פסנתר וקולות שנבנים לאט, כמו תפילה.'),
])
